window.POLKA_QUESTIONS=[{"id":"b000","q":"Есть ли у человека свобода воли?","tags":["Философия","Наука"],"sides":[["Нет","Каждое решение есть результат генов, среды и состояния мозга, которые мы не выбирали","Роберт Сапольски"],["Да, и она совместима с причинностью","Свободен тот, кто действует по своим причинам без принуждения, даже если причины имеют причины","Дэниел Деннет, Юм"],["Да, и она ничем не обусловлена","Без настоящего выбора нет ни ответственности, ни морали","Кант, Сартр"]],"note":"","draft":"Скорее да, в скромном смысле: у решений есть причины, но остаётся разница между поступком по своим мотивам и поступком под принуждением. Ответственность нужна как практика, даже если «конечного» выбора нет."},{"id":"b001","q":"Объективна ли мораль?","tags":["Философия"],"sides":[["Да","Некоторые вещи плохи независимо от мнений, как в математике есть истины независимо от нас","Дерек Парфит"],["Нет","Мораль выражает чувства и интересы, у разных культур она разная","Юм, Ницше"],["Она не объективна, но и не произвольна","Мораль решает общую задачу совместной жизни, и одни решения работают лучше других","Филип Китчер"]],"note":"","draft":"Не как физический факт, но и не дело вкуса: мораль решает задачу совместной жизни, и некоторые ответы настолько устойчивы, что работают как объективные."},{"id":"b002","q":"Что важнее в поступке: последствия или правила?","tags":["Философия"],"sides":[["Последствия","Правильно то, что даёт наибольшее благо наибольшему числу людей","Бентам, Милль"],["Правила","Человека нельзя использовать как средство, каким бы ни был выигрыш","Кант"],["Характер","Вопрос не в поступке, а в том, каким человеком он вас делает","Аристотель"]],"note":"","draft":"Последствия важнее в большинстве случаев, но правила нужны как защита от самообмана: тот, кто разрешает себе нарушать их «ради блага», обычно ошибается в расчётах."},{"id":"b003","q":"Обязаны ли мы помогать далёким незнакомцам?","tags":["Философия","Общество"],"sides":[["Да, так же как близким","Расстояние не меняет ценности жизни: если можешь спасти без большой жертвы, должен","Питер Сингер"],["Нет, близкие важнее","У нас особые обязательства перед семьёй и согражданами, без них мораль нечеловечна","Бернард Уильямс"],["Помогать хорошо, но это не долг","Благотворительность заслуживает похвалы именно потому, что её нельзя требовать","Традиционная этика"]],"note":"","draft":"Обязаны больше, чем делаем, но меньше, чем требует Сингер: у близких законный приоритет, а помощь далёким — долг в разумной доле дохода, не до самопожертвования."},{"id":"b004","q":"Можно ли есть животных?","tags":["Философия","Общество"],"sides":[["Нет","Способность страдать, а не вид, определяет, чьи интересы считать","Питер Сингер"],["Да","Мораль возникает между теми, кто способен на взаимные обязательства","Роджер Скрутон"],["Можно, но не так","Проблема не в самом употреблении, а в промышленном содержании","Движение за благополучие животных"]],"note":"","draft":"Сам вопрос спорен, но промышленное содержание защитить трудно: страдание реально, альтернативы доступны. Минимальная честная позиция — есть меньше и знать, откуда."},{"id":"b005","q":"Сводится ли сознание к работе мозга?","tags":["Философия","Наука"],"sides":[["Да","Сознание есть то, что делает мозг; загадка исчезнет, как исчезла загадка жизни","Дэниел Деннет"],["Нет","Никакое описание нейронов не объясняет, почему есть субъективный опыт","Дэвид Чалмерс, Томас Нагель"],["Мы пока не знаем, как ставить вопрос","Нужна новая теория, возможно меняющая представление о материи","Интегрированная информация, панпсихизм"]],"note":"","draft":"Сознание почти наверняка производится мозгом, но объяснения, почему этим процессам сопутствует переживание, пока нет. От мозга зависит точно, сводится ли к нему — неизвестно."},{"id":"b006","q":"Есть ли у жизни смысл?","tags":["Философия","Религия"],"sides":[["Нет, и с этим можно жить","Мир молчит, но бунт и ясность сами делают жизнь достойной","Камю"],["Смысл создаётся","Его не находят готовым, а берут на себя: в деле, любви, отношении к страданию","Виктор Франкл, Сартр"],["Смысл дан свыше","Без Бога и бессмертия любое дело обесценивается смертью","Толстой, «Исповедь»"]],"note":"","draft":"Готового смысла, скорее всего, нет, но жизнь от этого не становится бессмысленной: смысл возникает из привязанностей и дел, которые важны изнутри."},{"id":"b007","q":"Что важнее: свобода или равенство?","tags":["Философия","Политика"],"sides":[["Свобода","Любое перераспределение есть принуждение: человек владеет собой и плодами своего труда","Роберт Нозик"],["Равенство возможностей","Справедливы только те неравенства, которые улучшают положение наименее обеспеченных","Джон Ролз"],["Их нельзя взвесить раз и навсегда","Ценности конфликтуют, и каждое общество ищет свой компромисс","Исайя Берлин"]],"note":"","draft":"В общем виде не решается. Рабочая формула: базовые свободы неприкосновенны, а неравенство терпимо, пока не закрывает другим старт и не покупает власть."},{"id":"b008","q":"Подключились бы вы к машине, дающей идеальную жизнь в иллюзии?","tags":["Философия"],"sides":[["Да","Важно только то, что мы переживаем","Гедонизм, Эпикур, Бентам"],["Нет","Мы хотим не казаться, а быть и делать на самом деле","Роберт Нозик"]],"note":"","draft":"Нет. Хочется не только ощущений, но и чтобы они были о настоящем: реальные люди, реальные достижения."},{"id":"b009","q":"Обязаны ли мы чем-то будущим поколениям?","tags":["Философия","Общество"],"sides":[["Да, и очень многим","Будущих людей может быть в тысячи раз больше, их интересы весят столько же","Уильям Макаскилл"],["В ограниченной мере","Нельзя жертвовать живыми ради гипотетических; будущее слишком неопределённо","Критики лонгтермизма"],["Достаточно не вредить","Долг в том, чтобы оставить не худший мир, а не строить лучший","Ханс Йонас"]],"note":"","draft":"Обязаны не оставлять необратимого ущерба. Но жертвовать живыми ради расчётов о далёком будущем нельзя: слишком велика неопределённость."},{"id":"b010","q":"Вправе ли человек выбрать собственную смерть?","tags":["Философия","Общество"],"sides":[["Да","Автономия включает право решать о конце жизни; запрет продлевает страдания","Джон Харрис, практика Нидерландов"],["Нет","Разрешение создаёт давление на слабых и меняет смысл медицины","Леон Касс"],["Да, при жёстких условиях","Только неизлечимая болезнь, ясное сознание и несколько проверок","Законы Орегона и Швейцарии"]],"note":"","draft":"Довод автономии силён, довод о давлении на уязвимых тоже. Спор в основном о том, можно ли построить надёжные гарантии, и опыт стран, где это разрешено, оценивают по-разному."},{"id":"b011","q":"Наука открывает истину или строит полезные модели?","tags":["Наука","Философия"],"sides":[["Истину","Успех предсказаний был бы чудом, если бы теории не описывали реальность","Хилари Патнэм"],["Модели","Теории меняются целиком, как физика Ньютона; остаётся только то, что работает","Бас ван Фраассен"],["Парадигмы","Учёные видят мир через принятую рамку, и смена рамки не просто уточнение","Томас Кун"]],"note":"","draft":"Модели, которые подходят всё ближе к истине. Теории сменяются, но то, что они улавливали верно, обычно переходит в следующие."},{"id":"b012","q":"Гены или среда?","tags":["Наука","Психология"],"sides":[["Гены значат больше, чем принято думать","Близнецы, выросшие врозь, удивительно похожи","Стивен Пинкер, Роберт Пломин"],["Среда","Наследуемость ничего не говорит о том, что можно изменить; бедность перекрывает задатки","Ричард Нисбетт"],["Вопрос поставлен неверно","Ген действует только в конкретной среде, их вклад нельзя разделить","Роберт Сапольски"]],"note":"","draft":"И то и другое, причём не суммой: гены задают диапазон и чувствительность, среда определяет, что реализуется. Высокая наследуемость не значит «неизменно»."},{"id":"b013","q":"Можно ли редактировать геном будущих детей?","tags":["Наука","Философия"],"sides":[["Да","Если можем избавить ребёнка от болезни или дать ему преимущество, мы должны","Джулиан Савулеску"],["Нет","Ребёнок становится проектом родителей; исчезает принятие данного","Майкл Сэндел"],["Только чтобы лечить","Границу между лечением и улучшением провести трудно, но нужно","Позиция большинства регуляторов"]],"note":"","draft":"Лечить тяжёлые наследственные болезни — да, когда метод станет безопасным. Улучшать — нет: риски неизвестны, а выгоду получат те, у кого и так преимущество."},{"id":"b014","q":"Математику открывают или изобретают?","tags":["Наука","Философия"],"sides":[["Открывают","Простые числа были бы теми же в любой вселенной","Харди, Гёдель"],["Изобретают","Это игра по выбранным правилам; другие аксиомы дают другую математику","Формализм, Гильберт"],["Странно, что она вообще подходит миру","Изобретённое не должно так точно описывать физику","Юджин Вигнер"]],"note":"","draft":"Изобретают аксиомы и язык, открывают следствия: выбрав правила, мы уже не властны над тем, что из них вытекает."},{"id":"b015","q":"Одни ли мы во Вселенной?","tags":["Наука"],"sides":[["Скорее всего одни","Сложная жизнь требует цепочки маловероятных совпадений","Гипотеза редкой Земли"],["Нет, но цивилизации недолговечны","Где-то впереди или позади нас есть «великий фильтр»","Робин Хэнсон"],["Мы просто мало искали","Проверена ничтожная доля неба и частот","Джилл Тартер, SETI"]],"note":"","draft":"Неизвестно, и это честный ответ. Микробная жизнь где-то вероятна; разумная, с которой можно связаться, возможно, крайне редка."},{"id":"b016","q":"Рационален ли человек?","tags":["Психология","Экономика"],"sides":[["Нет","Мы систематически ошибаемся в вероятностях, и ошибки предсказуемы","Канеман и Тверски"],["Да, в своей среде","Простые эвристики часто работают лучше сложных расчётов","Герд Гигеренцер"],["Рациональность есть навык","Ошибки не приговор, им можно противостоять привычками и процедурами","Филип Тетлок"]],"note":"","draft":"Ограниченно: ошибки систематичны, но в привычной среде быстрые правила работают неплохо. Хуже всего с вероятностями, большими числами и далёким будущим."},{"id":"b017","q":"Можно ли изменить характер?","tags":["Психология"],"sides":[["Почти нет","Черты «большой пятёрки» во многом наследуются и стабильны десятилетиями","Исследования личности"],["Да","Вера в то, что способности растут, сама меняет результат","Кэрол Дуэк"],["Медленно и не всё","Черты сдвигаются с возрастом и ролями, но в пределах","Брент Робертс"]],"note":"","draft":"Темперамент меняется мало, привычки и поведение — заметно. Реалистичная цель — не стать другим человеком, а сдвинуться в пределах своего диапазона."},{"id":"b018","q":"От чего зависит счастье: от обстоятельств или от нас?","tags":["Психология"],"sides":[["От нас","К хорошему и плохому привыкают, уровень возвращается к базовому","Гедонистическая адаптация"],["От обстоятельств","Доход, здоровье и безопасность заметно связаны с благополучием","Мэттью Киллингсворт"],["От отношений","Лучший предсказатель хорошей жизни есть близкие связи","Гарвардское исследование развития взрослых"]],"note":"","draft":"Обстоятельства важны до порога: здоровье, безопасность, достаток. Дальше решают отношения и то, на что направлено внимание."},{"id":"b019","q":"Любовь — чувство или навык?","tags":["Психология","Философия"],"sides":[["Навык","Любить значит действовать: заботиться, знать, уважать","Эрих Фромм"],["Чувство и биология","Влечение, влюблённость и привязанность есть три системы мозга","Хелен Фишер"],["Сначала чувство, потом работа","Влюблённость случается, отношения строятся","Джон Готтман"]],"note":"","draft":"Влюблённость — чувство, оно случается. Любовь на годы — навык: внимание, щедрость в толковании чужих поступков, умение ссориться."},{"id":"b020","q":"Историю делают личности или безличные силы?","tags":["История","Философия"],"sides":[["Личности","Без Наполеона, Ленина или Петра всё пошло бы иначе","Томас Карлейль"],["Силы","Экономика, география и массы решают; вожди лишь ярлыки событий","Маркс, Толстой"],["Личности в узких местах","Обычно решают структуры, но в моменты кризиса один человек меняет развилку","Сидни Хук"]],"note":"","draft":"Силы задают коридор возможного, личности выбирают путь внутри него. Чем острее кризис, тем больше весит один человек."},{"id":"b021","q":"Почему пала Западная Римская империя?","tags":["История"],"sides":[["Внутреннее разложение","Упадок гражданской доблести, экономики и управления","Эдвард Гиббон"],["Её разрушили извне","Гунны и германцы нанесли удары, которых не выдержала бы никакая система","Питер Хизер"],["Она не пала, а преобразилась","Античный мир постепенно перешёл в средневековый","Питер Браун"]],"note":"","draft":"Причин несколько: давление извне наложилось на гражданские войны, финансовый кризис и раскол империи. Восток прожил ещё тысячу лет, значит, внутреннее устройство имело значение."},{"id":"b022","q":"Почему промышленная революция случилась в Европе, а не в Китае?","tags":["История","Экономика"],"sides":[["География","Раздробленность Европы создавала конкуренцию, уголь лежал рядом","Джаред Даймонд, Кеннет Померанц"],["Институты","Защита собственности и ограничение власти","Аджемоглу и Робинсон"],["Культура знания","Сообщество учёных и уважение к полезным изобретениям","Джоэль Мокир"]],"note":"","draft":"Сочетание факторов: раздробленность и конкуренция государств, доступный уголь, дорогой труд, культура практического знания. Ни одного по отдельности не хватает."},{"id":"b023","q":"Можно ли судить людей прошлого по сегодняшним меркам?","tags":["История","Философия"],"sides":[["Нет","Каждый человек ограничен горизонтом своей эпохи","Историзм"],["Да","В любую эпоху были те, кто видел зло и говорил о нём","Аболиционисты как пример"],["Судить поступки, понимать людей","Оценка нужна, но она не заменяет объяснения","Марк Блок"]],"note":"","draft":"Понимать — по меркам их времени, оценивать — по нашим, не путая одно с другим. И помнить, что нас будут судить так же."},{"id":"b024","q":"Были ли оправданы бомбардировки Хиросимы и Нагасаки?","tags":["История","Философия"],"sides":[["Да","Вторжение в Японию стоило бы больше жизней с обеих сторон","Официальная позиция США 1945 года"],["Нет","Намеренное убийство гражданских не оправдывается никакой целью","Элизабет Энском"],["Не они решили дело","Япония капитулировала главным образом из-за вступления СССР в войну","Цуёси Хасэгава"]],"note":"","draft":"Историки расходятся. Довод о спасённых жизнях опирается на оценки потерь при вторжении, которые оспаривают; довод против — на то, что Япония была близка к капитуляции и что удар по городу недопустим сам по себе."},{"id":"b025","q":"Есть ли в истории прогресс?","tags":["История","Философия"],"sides":[["Да","Насилие, бедность и смертность снижаются веками","Стивен Пинкер"],["Нет","Техника растёт, человек остаётся тем же; XX век это показал","Джон Грей, Вальтер Беньямин"],["Есть, но он обратим","Достижения держатся на институтах, которые можно потерять","Карл Поппер"]],"note":"","draft":"В материальном и медицинском — безусловно. В моральном он есть, но не гарантирован и обратим: XX век показал, как быстро теряется достигнутое."},{"id":"b026","q":"Была ли революция 1917 года неизбежной?","tags":["История"],"sides":[["Да","Нерешённые аграрный и рабочий вопросы плюс негибкая монархия","Советская историография, Леопольд Хеймсон"],["Нет","Россия быстро развивалась, её сорвала мировая война","Ричард Пайпс, «оптимисты»"],["Февраль был вероятен, Октябрь нет","Падение монархии назревало, приход большевиков был стечением обстоятельств","Александр Рабинович"]],"note":"","draft":"Кризис монархии был глубоким, но исход определила война. Без неё вероятнее медленная эволюция; приход к власти именно большевиков зависел от многих случайностей."},{"id":"b027","q":"Пётр I: модернизация или надлом?","tags":["История"],"sides":[["Модернизация","Без армии, флота и науки Россия осталась бы на периферии","Сергей Соловьёв"],["Надлом","Раскол между европеизированной элитой и народом, усиление крепостничества","Славянофилы, Николай Карамзин"],["И то и другое","Цель была верной, цена и методы закрепили принуждение","Василий Ключевский"]],"note":"","draft":"И то и другое: без его реформ не было бы ни державы, ни науки, но методы закрепили принуждение и разрыв между элитой и остальными."},{"id":"b028","q":"Демократия — лучшая форма правления?","tags":["Политика","Философия"],"sides":[["Да","Она позволяет сменить власть без крови и исправлять ошибки","Карл Поппер"],["Нет","Избиратели невежественны; править должны знающие","Платон, Джейсон Бреннан"],["Смотря с какими институтами","Выборы без суда, прессы и прав меньшинства дают тиранию большинства","Токвиль, Мэдисон"]],"note":"","draft":"Главный довод за — не мудрость большинства, а возможность мирно сменить власть и исправить ошибку. Главный довод против — качество решений. Многое зависит от суда, прессы и защиты меньшинства."},{"id":"b029","q":"Где границы свободы слова?","tags":["Политика","Философия"],"sides":[["Почти нигде","Запрещая мнение, мы теряем либо истину, либо её живое понимание","Джон Стюарт Милль"],["Там, где начинается вред","Речь ненависти лишает людей равного достоинства","Джереми Уолдрон"],["Государство не должно, общество может","Цензура недопустима, но у слов есть социальные последствия","Современный либеральный компромисс"]],"note":"","draft":"Спорят не о том, нужны ли границы (призывы к насилию и клевета ограничены везде), а о том, где они проходят и кто их проводит. Чем шире право запрещать, тем выше риск, что его применят к неудобной критике."},{"id":"b030","q":"Можно ли нарушать несправедливый закон?","tags":["Политика","Философия"],"sides":[["Да","Несправедливый закон не закон; открытое нарушение с готовностью понести наказание","Мартин Лютер Кинг, Торо"],["Нет","Живя в государстве, вы согласились с его законами","Сократ в «Критоне»"],["Только как крайнее средство","Когда исчерпаны законные пути и нарушение ненасильственно","Джон Ролз"]],"note":"","draft":"Можно, если закон грубо несправедлив, законные пути исчерпаны, действие ненасильственно и человек готов нести последствия. Иначе это просто нарушение."},{"id":"b031","q":"Допустима ли смертная казнь?","tags":["Политика","Философия"],"sides":[["Нет","Она не сдерживает лучше пожизненного, а ошибку нельзя исправить","Чезаре Беккариа"],["Да","За убийство справедливо только равное воздаяние","Кант"],["В принципе да, на практике нет","Ни одна судебная система не достаточно точна","Данные о судебных ошибках"]],"note":"","draft":"Спор держится на двух вопросах: требует ли справедливость равного воздаяния и можно ли мириться с необратимой судебной ошибкой. Данные о сдерживающем эффекте неубедительны в обе стороны."},{"id":"b032","q":"Нужны ли открытые границы?","tags":["Политика","Экономика"],"sides":[["Да","Место рождения есть лотерея; свободная миграция резко увеличила бы мировое богатство","Брайан Каплан, Джозеф Каренс"],["Нет","Сообщество вправе решать, кого принимать","Майкл Уолцер, Дэвид Миллер"],["Больше, но управляемо","Выгоды велики, но темп должен позволять интеграцию","Пол Коллиер"]],"note":"","draft":"Экономисты в целом согласны, что миграция увеличивает общее богатство; спорят о распределении выгод, о темпе и о праве сообщества решать. Ответ зависит от того, как взвешивать интересы приезжающих и принимающих."},{"id":"b033","q":"Мир становится лучше?","tags":["Общество","История"],"sides":[["Да","Бедность, детская смертность и неграмотность упали до исторических минимумов","Ханс Рослинг, Стивен Пинкер"],["Картина приукрашена","Порог бедности занижен, а экологическая цена роста не учтена","Джейсон Хикель"],["Лучше, но хрупко","Прошлые успехи не гарантируют будущих","Our World in Data"]],"note":"","draft":"По здоровью, грамотности и бедности — да, и намного. По климату и биоразнообразию — хуже. Обе вещи верны одновременно."},{"id":"b034","q":"Климат: личные усилия или системные решения?","tags":["Общество","Политика"],"sides":[["Системные","Вклад одного человека ничтожен; решают цена углерода и энергетика","Экономисты климата"],["Личные тоже","Нормы меняются с людей, а спрос формирует рынок","Питер Сингер"],["Личный выбор как политика","Важнее всего то, как вы голосуете и где работаете","Ханна Ричи"]],"note":"","draft":"Основной эффект дают системные решения. Личные имеют смысл как норма и сигнал, но политику и технологии не заменяют."},{"id":"b035","q":"Нужна ли атомная энергетика?","tags":["Общество","Наука"],"sides":[["Да","Низкоуглеродная, стабильная и по смертности на единицу энергии одна из самых безопасных","Вацлав Смил, Our World in Data"],["Нет","Дорого, долго строить, отходы и риск аварий","Опыт Германии"],["Сохранять, но ставить на возобновляемые","Не закрывать работающие станции, новые строить там, где это дешевле альтернатив","МЭА"]],"note":"","draft":"Скорее да: по безопасности и выбросам данные в её пользу. Настоящие слабости — стоимость и сроки строительства, а не аварии."},{"id":"b036","q":"Эффективны ли финансовые рынки?","tags":["Экономика"],"sides":[["Да","Цены отражают доступную информацию; систематически обыграть рынок нельзя","Юджин Фама"],["Нет","Пузыри и избыточная волатильность показывают, что ценами движут настроения","Роберт Шиллер"],["Они адаптивны","Эффективность меняется со временем, как экосистема","Эндрю Ло"]],"note":"","draft":"В основном да в смысле «трудно систематически обыграть» и нет в смысле «цена всегда верна». Эффективность — результат конкуренции, и она разная на разных рынках и горизонтах."},{"id":"b037","q":"Почему одни страны богатые, а другие бедные?","tags":["Экономика","История"],"sides":[["Институты","Растут там, где защищена собственность и власть ограничена","Аджемоглу и Робинсон"],["География","Климат, болезни, выход к морю задают стартовые условия","Джеффри Сакс, Джаред Даймонд"],["Политика государства","Все богатые страны защищали свою промышленность, пока не разбогатели","Ха-Джун Чхан"]],"note":"","draft":"Институты объясняют больше всего, но сами они выросли из географии и истории. Одного ключа нет."},{"id":"b038","q":"Кейнс или Хайек?","tags":["Экономика","Политика"],"sides":[["Кейнс","В кризис рынок застревает; бездействие стоит лет безработицы","Великая депрессия, 2008 год"],["Хайек","Вмешательство искажает цены и готовит следующий кризис","Стагфляция 1970-х"],["Оба правы в разное время","Кейнс нужен в провале спроса, Хайек в долгом периоде","Николас Уопшотт"]],"note":"","draft":"Кейнс прав о кризисах спроса, Хайек — о пределах знания у планировщика. Ошибка — применять одного там, где нужен другой."},{"id":"b039","q":"Неравенство: проблема или плата за рост?","tags":["Экономика","Общество"],"sides":[["Проблема само по себе","Концентрация богатства превращается в концентрацию власти","Тома Пикетти"],["Важна бедность, а не разрыв","Если бедные живут лучше, неважно, насколько богаты богатые","Гарри Франкфурт"],["Смотря откуда оно","Богатство от инноваций полезно, от ренты и связей вредно","Ангус Дитон"]],"note":"","draft":"Зависит от источника и от мобильности: терпимо, когда оно от созданной ценности и не наследуется как каста; опасно, когда превращается в политическую власть."},{"id":"b040","q":"Нужен ли безусловный базовый доход?","tags":["Экономика","Политика"],"sides":[["Да","Проще и достойнее, чем десятки пособий с проверками","От Фридмана до ван Парейса"],["Нет","Слишком дорого для заметной суммы; деньги лучше направить нуждающимся","Дарон Аджемоглу"],["Сначала проверить","Пилоты показали, что работать не бросают, но масштаб страны не проверен","Банерджи и Дюфло"]],"note":"","draft":"Данных в масштабе страны нет. Пилоты показывают, что работать люди не бросают; открытый вопрос — цена и что придётся сократить взамен."},{"id":"b041","q":"Меритократия справедлива?","tags":["Общество","Философия"],"sides":[["Да, это лучшее из имеющегося","Места достаются способным, а не родовитым","Адриан Вулдридж"],["Нет, она унижает проигравших","Успех зависит от семьи и везения, но победители считают его заслугой","Майкл Сэндел"],["Её просто нет","Культурный капитал наследуется; школа выдаёт происхождение за талант","Пьер Бурдьё"]],"note":"","draft":"Как принцип отбора она лучше альтернатив, как моральная оценка людей — ложна: старт неравен, а талант тоже удача."},{"id":"b042","q":"Вкус: личное дело или классовый маркер?","tags":["Общество","Искусство"],"sides":[["Маркер","Любовь к опере или к шансону предсказывается происхождением","Пьер Бурдьё"],["Личное дело","Сегодня образованные люди слушают всё подряд","Ричард Питерсон"],["Всеядность и есть новый маркер","Умение смешивать высокое и низкое тоже требует капитала","Продолжатели Бурдьё"]],"note":"","draft":"В значительной мере маркер, но не только: внутри любого класса вкусы различаются, а насмотренность можно нажить."},{"id":"b043","q":"Можно ли осуждать чужие обычаи?","tags":["Общество","Философия"],"sides":[["Нет","Наши мерки тоже продукт культуры","Франц Боас, Рут Бенедикт"],["Да","Есть практики, причиняющие очевидный вред; права человека не зависят от границ","Марта Нуссбаум"],["Понимать и судить порознь","Релятивизм нужен как метод изучения, но не запрещает оценку","Клиффорд Гирц"]],"note":"","draft":"Можно, если сначала понять и если критерий — вред конкретным людям, а не непохожесть на нас."},{"id":"b044","q":"Соцсети вредят обществу?","tags":["Общество","Психология"],"sides":[["Да","Рост тревоги у подростков совпал с приходом смартфонов","Джонатан Хайдт"],["Данные слабые","Связь мала и корреляционна","Кэндис Оджерс, Эндрю Пшибыльски"],["Смотря как пользоваться","Пассивное листание вредит, общение с близкими помогает","Исследования типов использования"]],"note":"","draft":"Для большинства эффект небольшой; для части подростков, вероятно, вредный. Сказать больше данные пока не позволяют."},{"id":"b045","q":"Нужна ли религия для морали?","tags":["Религия","Философия"],"sides":[["Да","Если Бога нет, всё позволено","Достоевский, Иван Карамазов"],["Нет","Сочувствие и справедливость есть у приматов и у неверующих обществ","Франс де Вааль"],["Не для морали, а для общности","Ритуал связывает людей в группы, которые держатся дольше","Джонатан Хайдт, Дюркгейм"]],"note":"","draft":"Нет: неверующие не менее моральны. Но религия давала общность и ритуал, и чем это заменить, до конца не ясно."},{"id":"b046","q":"Совместимы ли наука и религия?","tags":["Религия","Наука"],"sides":[["Да, у них разные области","Наука отвечает на «как», религия на «зачем»","Стивен Джей Гулд"],["Нет","Религия делает утверждения о мире, и они не проходят проверку","Ричард Докинз"],["Исторически они союзники","Университеты и многие учёные выросли из церкви","Историки науки"]],"note":"","draft":"Совместимы, пока религия не делает проверяемых утверждений о мире. Конфликт начинается там, где она их делает."},{"id":"b047","q":"Нужен ли литературный канон?","tags":["Литература"],"sides":[["Да","Есть книги, которые выдержали века; без общего списка нет общего разговора","Гарольд Блум"],["Нет в прежнем виде","Канон составляли немногие, и он отражает их кругозор","Критика канона с 1980-х"],["Нужен открытый канон","Список полезен, если его пересматривают","Итало Кальвино"]],"note":"","draft":"Нужен как общий язык и как отбор временем, при условии что его пересматривают."},{"id":"b048","q":"Важно ли, что хотел сказать автор?","tags":["Литература","Философия"],"sides":[["Нет","Текст живёт в чтении, автор над ним не властен","Ролан Барт"],["Да","Без замысла автора любое толкование равно любому другому","Эрик Хирш"],["Замысел есть одно из свидетельств","Его учитывают, но текст может сказать больше","Умберто Эко"]],"note":"","draft":"Важно, но не решает: текст может значить больше, чем автор вкладывал, но не что угодно."},{"id":"b049","q":"Делает ли чтение романов нас лучше?","tags":["Литература","Психология"],"sides":[["Да","Роман тренирует способность видеть мир глазами другого","Марта Нуссбаум"],["Нет","Начитанные люди совершали ужасное; данные об эмпатии слабые","Грегори Карри"],["Оно делает нас сложнее","Не добрее, но внимательнее к оттенкам","Набоков"]],"note":"","draft":"Добрее само по себе не делает. Оно расширяет запас чужих жизней и точность языка; что с этим делать, решает читатель."},{"id":"b050","q":"Что считать искусством?","tags":["Искусство","Философия"],"sides":[["То, что признал мир искусства","Писсуар стал искусством, когда его выставили","Марсель Дюшан, Джордж Дики"],["То, в чём есть мастерство и красота","Без них остаётся жест","Роджер Скрутон"],["То, что передаёт чувство","Искусство есть заражение переживанием","Лев Толстой"]],"note":"","draft":"То, что сделано, чтобы на это смотрели как на искусство, и что такое смотрение выдерживает. Признание музеев необходимо, но недостаточно."},{"id":"b051","q":"Нужно ли возвращать музейные ценности в страны происхождения?","tags":["Искусство","История"],"sides":[["Да","Они вывезены при неравенстве сил и принадлежат культуре, которая их создала","Позиция Греции по мраморам Парфенона"],["Нет","Универсальный музей показывает человечество целиком и сохранил эти вещи","Нил Макгрегор"],["Смотря как вывезено","Награбленное возвращать, купленное законно обсуждать","Доклад Сарра и Савуа"]],"note":"","draft":"Награбленное и вывезенное силой — возвращать. Остальное решать по отдельности, с учётом сохранности и доступа для зрителей."},{"id":"b052","q":"Есть ли объективно великая музыка?","tags":["Музыка","Философия"],"sides":[["Да","Сложность, новизна и влияние измеримы; Бах прошёл проверку трёх веков","Леонард Бернстайн"],["Нет, есть только вкус","Канон составили европейцы определённого класса","Бурдьё, этномузыкология"],["Великая в своей традиции","Сравнивать можно внутри жанра по его правилам","Тед Джойя"]],"note":"","draft":"Внутри одной традиции — да, и это можно показать разбором. Между традициями общих критериев нет."},{"id":"b053","q":"Классика элитарна?","tags":["Музыка","Общество"],"sides":[["Да","Ритуал концерта, цена билета и подготовка отсекают большинство","Социология вкуса"],["Нет","Запись сделала её бесплатной; в XIX веке оперу напевали на улицах","Алекс Росс"],["Элитарна подача","Барьер создают дресс-код и тон разговора о ней","Опыт Бернстайна"]],"note":"","draft":"Сама музыка — нет, она доступна бесплатно. Элитарны ритуал и привычка слушать, которым никто не учит."},{"id":"b054","q":"Можно ли слушать Вагнера, зная его взгляды?","tags":["Музыка","Философия"],"sides":[["Да","Музыка не содержит высказываний; отказ ничего не исправит","Даниэль Баренбойм"],["Нет или не везде","Он писал антисемитские тексты, нацисты сделали его символом","Негласный запрет в Израиле"],["Слушать, зная контекст","Знание истории делает слушание честнее","Алекс Росс"]],"note":"","draft":"Можно. Музыка его взглядов не несёт, но знать о них стоит, а отказ исполнять его в некоторых местах понятен."},{"id":"b055","q":"Музыка, написанная ИИ, — это музыка?","tags":["Музыка","Технологии"],"sides":[["Да","Если слушатель тронут, происхождение неважно","Опыты Дэвида Коупа"],["Нет","Музыка есть сообщение от человека человеку","Романтическая традиция"],["Это инструмент","Синтезатор и сэмплер тоже объявляли концом музыки","История технологий"]],"note":"Собирал это ИИ, так что в этом вопросе я заинтересованная сторона.","draft":"Как звук — да. Как высказывание — только если за ней стоит чей-то выбор и намерение."},{"id":"b056","q":"Режиссёр — автор фильма?","tags":["Кино"],"sides":[["Да","У больших режиссёров узнаваемый почерк при любом сценарии","Франсуа Трюффо, Эндрю Саррис"],["Нет","Сценарист, оператор, монтажёр часто важнее","Полин Кейл"],["Автор тот, у кого власть","В студийную эпоху это продюсер, в сериалах шоураннер","История Голливуда"]],"note":"","draft":"Чаще да, чем нет, но кино коллективно, и каждый раз стоит смотреть, кто на самом деле принимал решения."},{"id":"b057","q":"Можно ли отделить произведение от автора?","tags":["Кино","Философия"],"sides":[["Да","Произведение живёт отдельно; иначе придётся выбросить половину канона","Ролан Барт"],["Нет","Просмотр приносит автору деньги и славу, его взгляды вшиты в работу","Споры о «Рождении нации»"],["Смотреть можно, чествовать нельзя","Изучать и награждать есть разные действия","Клер Дедерер"]],"note":"","draft":"Произведение можно оценивать отдельно. Платить автору и чествовать его — отдельное решение, и оно зависит от того, жив ли он и что сделал."},{"id":"b058","q":"Супергеройские фильмы — это кино?","tags":["Кино"],"sides":[["Нет, это аттракцион","В них нет риска и откровения","Мартин Скорсезе"],["Да","Жанровое кино презирали всегда, включая Хичкока","Критики Cahiers du cinéma"],["Вопрос не в жанре","Проблема в том, что франшизы вытесняют средние фильмы из проката","Экономика проката"]],"note":"","draft":"Это кино, просто чаще всего осторожное. Претензия не к жанру, а к конвейеру."},{"id":"b059","q":"Стриминг убивает кино?","tags":["Кино","Технологии"],"sides":[["Да","Кино задумано для большого экрана и общего зала","Кристофер Нолан"],["Нет","Он даёт деньги авторам и доступ зрителям","«Рома», «Ирландец»"],["Кино уже умирало","То же говорили о звуке, телевидении и видео","История кино"]],"note":"","draft":"Не убивает, но меняет: средний фильм ушёл из кинотеатров, а внимание зрителя стало дробным."},{"id":"b060","q":"Понимают ли языковые модели то, что говорят?","tags":["Технологии","Философия"],"sides":[["Нет","Они предсказывают слова по статистике, не имея связи с миром","Эмили Бендер, «стохастические попугаи»"],["Да, в каком-то смысле","Чтобы хорошо предсказывать текст, нужно строить модель мира","Джеффри Хинтон"],["Слово «понимать» надо уточнить","Есть разные способности, и у моделей они развиты неравномерно","Мелани Митчелл"]],"note":"Этот список составил ИИ, так что здесь я заинтересованная сторона. Проверяйте доводы строже обычного.","draft":"Зависит от определения. Модели явно улавливают структуру смысла, но опыта мира у них нет, и ошибаются они иначе, чем люди."},{"id":"b061","q":"Опасен ли ИИ для человечества?","tags":["Технологии","Философия"],"sides":[["Да, это риск уровня вымирания","Система умнее нас с чуть неверной целью неконтролируема","Стюарт Рассел, Ник Бостром"],["Нет, это отвлекает от реальных проблем","Важнее предвзятость, дезинформация и концентрация власти уже сейчас","Тимнит Гебру"],["Риск есть, но решаемый","Это инженерная задача, как безопасность самолётов","Ян Лекун"]],"note":"Здесь я тоже заинтересованная сторона.","draft":"Серьёзные исследователи расходятся. Риск нельзя считать ни доказанным, ни выдуманным; разумно готовиться и к ближним вредам, и к дальним."},{"id":"b062","q":"Заберёт ли ИИ работу у людей?","tags":["Технологии","Экономика"],"sides":[["Да, в этот раз иначе","Автоматизируется не мускульный, а умственный труд","Дэниел Сасскинд"],["Нет","Каждая волна техники создавала больше работ, чем уничтожала","Дэвид Отор"],["Работа останется, вопрос в доходах","Выигрыш может достаться владельцам капитала","Дарон Аджемоглу"]],"note":"","draft":"Часть задач исчезнет, часть появится. Главный вопрос — кому достанется выигрыш и насколько быстрым будет переход."},{"id":"o000","q":"Что вы знаете наверняка и откуда?","tags":["Философия"],"draft":"Наверняка — почти ничего, кроме того, что прямо сейчас есть опыт. Остальное известно с разной степенью уверенности, и этого хватает, чтобы действовать."},{"id":"o001","q":"Если бы вас скопировали атом в атом, копия была бы вами?","tags":["Философия"],"draft":"Для всех остальных — да. Для меня нынешней — нет: моё переживание к копии не перейдёт, у неё начнётся своё."},{"id":"o002","q":"Вы тот же человек, что десять лет назад? Что именно сохранилось?","tags":["Философия"],"draft":"Сохранились память и склад характера, сменились взгляды и почти все клетки. Тождество держится на непрерывности, а не на неизменности."},{"id":"o003","q":"Можно ли быть хорошим человеком, никому не помогая?","tags":["Философия"],"draft":"Безвредным — да, хорошим — вряд ли: доброта требует действия."},{"id":"o004","q":"Ложь во спасение: когда она допустима и кто это решает?","tags":["Философия"],"draft":"Допустима, когда правда ничего не изменит, кроме боли, и человек о ней не просил. Недопустима, когда отнимает у другого возможность решать."},{"id":"o005","q":"Есть ли поступок, который нельзя оправдать никакими последствиями?","tags":["Философия"],"draft":"Да: намеренное мучение невинного. Если расчёт его оправдывает, ошибся расчёт."},{"id":"o006","q":"Чем обещание отличается от намерения и почему его надо держать?","tags":["Философия"],"draft":"Обещание даёт другому право рассчитывать на тебя. Держать его надо потому, что на этом стоит доверие, без которого ничего совместного не построить."},{"id":"o007","q":"Заслуживает ли человек свои таланты?","tags":["Философия"],"draft":"Нет, талант — лотерея. Заслужить можно только то, что с ним сделано, да и это отчасти везение."},{"id":"o008","q":"Лучше быть недовольным Сократом или довольным глупцом?","tags":["Философия"],"draft":"Недовольным Сократом: тот, кто знает обе стороны, понимание на довольство не променяет."},{"id":"o009","q":"Что вы должны родителям и что они должны вам?","tags":["Философия"]},{"id":"o010","q":"Плохо ли умереть, если вас уже не будет, чтобы об этом жалеть?","tags":["Философия"],"draft":"Плохо не состояние смерти, а потеря того, что могло бы быть. Поэтому смерть в двадцать хуже, чем в девяносто."},{"id":"o011","q":"Захотели бы вы жить вечно? При каких условиях?","tags":["Философия"],"draft":"Только с возможностью остановиться и со здоровьем. Бесконечность без выхода страшнее смерти."},{"id":"o012","q":"Можно ли сравнивать страдания разных людей?","tags":["Философия"],"draft":"Точно — нет, грубо — да, и мы делаем это постоянно, когда решаем, кому помочь первым."},{"id":"o013","q":"Удача или заслуга: как вы делите собственную биографию?","tags":["Философия"]},{"id":"o014","q":"Есть ли у вас убеждение, которое вы не готовы пересматривать? Почему?","tags":["Философия"]},{"id":"o015","q":"Что бы изменилось в вашей жизни, если бы вы точно знали, что свободы воли нет?","tags":["Философия"],"draft":"В повседневности почти ничего. Стало бы меньше злости на других и гордости за себя."},{"id":"o016","q":"Обязаны ли мы быть счастливыми?","tags":["Философия"],"draft":"Нет. Счастье — побочный продукт, а не долг; требование быть счастливым само делает несчастным."},{"id":"o017","q":"Чем мудрость отличается от ума?","tags":["Философия"],"draft":"Ум решает задачи. Мудрость выбирает, какие стоит решать, и знает свои пределы."},{"id":"o018","q":"Какой философский вопрос вы считаете пустым и почему?","tags":["Философия"]},{"id":"o019","q":"Что такое хорошо прожитая жизнь? Опишите одним абзацем.","tags":["Философия"]},{"id":"o020","q":"Какая книга изменила то, как вы думаете, и что именно в ней сработало?","tags":["Литература"]},{"id":"o021","q":"Зачем читать вымысел, если есть нон-фикшн?","tags":["Литература"],"draft":"Нон-фикшн сообщает, что происходит. Роман даёт побыть тем, с кем это происходит."},{"id":"o022","q":"Анна Каренина: жертва, виновница или ни то ни другое?","tags":["Литература"],"draft":"Ни то ни другое: Толстой показывает, как страсть и общество вместе не оставляют ей выхода, и при этом не снимает с неё ответственности."},{"id":"o023","q":"Раскольников раскаялся или только проиграл?","tags":["Литература"],"draft":"В романе скорее проиграл: теория рухнула раньше, чем пришло раскаяние. Оно отнесено в эпилог и там только начинается."},{"id":"o024","q":"Кто прав в «Великом инквизиторе»: Христос или Инквизитор?","tags":["Литература"],"draft":"Инквизитор точнее описывает людей, Христос — то, какими они могли бы быть. Достоевский даёт Инквизитору лучшие доводы и всё же с ним не соглашается."},{"id":"o025","q":"Чем великая книга отличается от просто хорошей?","tags":["Литература"],"draft":"Хорошую помнят по сюжету. Великую перечитывают, и каждый раз она оказывается о другом."},{"id":"o026","q":"Нужно ли дочитывать книги, которые не нравятся?","tags":["Литература"],"draft":"Нет. Но трудную и неприятную стоит различать: первую иногда надо дотерпеть."},{"id":"o027","q":"Что теряется в переводе и что вы заметили, читая по-французски?","tags":["Литература"],"draft":"Теряются ритм, игра слов и регистр. Смысл доезжает, голос — не всегда."},{"id":"o028","q":"Может ли злодей быть главным героем, которому сочувствуешь? Что это говорит о нас?","tags":["Литература"],"draft":"Может. Сочувствие не одобрение: оно показывает, что мы понимаем мотивы, которые осуждаем."},{"id":"o029","q":"Школьная программа отбивает любовь к классике или даёт общий язык?","tags":["Литература"],"draft":"И то и другое. Общий язык она даёт; любовь отбивает не список, а то, что книги дают слишком рано и ждут правильного ответа."},{"id":"o030","q":"Какой литературный герой вам неприятен, потому что похож на вас?","tags":["Литература"]},{"id":"o031","q":"Счастливый конец: слабость или смелость автора?","tags":["Литература"],"draft":"Ни то ни другое само по себе. Слабость — конец, который не заработан, счастливый он или трагический."},{"id":"o032","q":"Поэзия сегодня кому-то нужна? Зачем?","tags":["Литература"],"draft":"Нужна тем же, кому всегда: тем, кому важно, как сказано. Их мало, и так было всегда."},{"id":"o033","q":"Что останется от литературы нашего времени через сто лет?","tags":["Литература"],"draft":"Скорее всего не то, что сейчас получает премии. Останется то, что будут перечитывать без напоминаний."},{"id":"o034","q":"Можно ли понять страну по её романам? Какую и по каким?","tags":["Литература"],"draft":"Отчасти: романы показывают, о чём страна спорит сама с собой. Францию — по Бальзаку и Флоберу, Россию — по Толстому и Чехову."},{"id":"o035","q":"Оруэлл или Хаксли: чья антиутопия ближе к сбывшейся?","tags":["Литература"],"draft":"Сбылись оба, в разных местах: слежка и переписывание прошлого по Оруэллу, развлечение как способ не думать по Хаксли."},{"id":"o036","q":"Перечитывание: что вы увидели в книге, вернувшись к ней старше?","tags":["Литература"]},{"id":"o037","q":"Имеет ли право писатель писать от лица тех, кем он не является?","tags":["Литература"],"draft":"Имеет: в этом и состоит литература. Вопрос только в том, хорошо ли это сделано."},{"id":"o038","q":"Какую одну книгу вы бы дали человеку, который не читает?","tags":["Литература"]},{"id":"o039","q":"Почему русская литература XIX века так занята вопросом «как жить»?","tags":["Литература"],"draft":"Других площадок не было: философия, политика и проповедь были под цензурой, и роман взял на себя всё."},{"id":"o040","q":"Какое событие прошлого сильнее всего определяет вашу сегодняшнюю жизнь?","tags":["История"]},{"id":"o041","q":"Если бы можно было отменить одно событие в истории, какое и что пошло бы иначе?","tags":["История"]},{"id":"o042","q":"Чему история на самом деле учит, если учит?","tags":["История"],"draft":"Не рецептам, а осторожности: показывает, как часто уверенные люди ошибались и как редко последствия совпадали с замыслом."},{"id":"o043","q":"Почему люди шли за диктаторами добровольно?","tags":["История"],"draft":"Им обещали порядок, достоинство и виноватого после унижения и хаоса. Страх пришёл позже, сначала было согласие."},{"id":"o044","q":"Что вы бы делали в 1937 году? Почему вы в этом уверены?","tags":["История"],"draft":"Честный ответ: скорее всего молчала бы, как большинство. Уверенность в собственном героизме ничем не проверена."},{"id":"o045","q":"Империи: только зло или ещё и порядок? Для кого?","tags":["История"],"draft":"Для завоёванных — насилие и изъятие, иногда вместе с дорогами, правом и миром на границах. Счёт зависит от того, кого спрашивать."},{"id":"o046","q":"Кто пишет историю и можно ли прочитать её против автора?","tags":["История"],"draft":"Победители и грамотные. Читать против автора можно: по тому, о чём он молчит и что считает само собой разумеющимся."},{"id":"o047","q":"Какой исторический миф вы считали правдой и когда перестали?","tags":["История"]},{"id":"o048","q":"Была ли Первая мировая случайностью?","tags":["История"],"draft":"Повод был случайным, готовность — нет: союзы, планы мобилизации и вера в короткую войну сделали так, что искры хватило."},{"id":"o049","q":"Наполеон: продолжатель революции или её могильщик?","tags":["История"],"draft":"И то и другое: закрепил равенство перед законом и кодекс, уничтожил республику и политическую свободу."},{"id":"o050","q":"Средневековье было «тёмным»? Откуда эта репутация?","tags":["История"],"draft":"Нет. Репутацию создали гуманисты Возрождения и просветители, которым нужен был тёмный фон. Университеты, готика и право — оттуда."},{"id":"o051","q":"Что важнее для понимания эпохи: войны и короли или цены на хлеб?","tags":["История"],"draft":"Цены на хлеб объясняют, почему случились войны; войны объясняют, что стало потом. Без первого второе непонятно."},{"id":"o052","q":"Нужны ли стране памятники тем, чьи взгляды сегодня неприемлемы?","tags":["История"],"draft":"Довод за сохранение: это свидетельство прошлого. Довод против: памятник — честь, а не учебник. Частый компромисс — музей и пояснение вместо площади."},{"id":"o053","q":"Должны ли потомки отвечать за то, что сделали предки?","tags":["История"],"draft":"Вины нет, ответственность есть: помнить, не отрицать и исправлять то, чем продолжаешь пользоваться."},{"id":"o054","q":"Какая эпоха вам ближе всего и что вы в ней идеализируете?","tags":["История"]},{"id":"o055","q":"Почему одни революции заканчиваются свободой, а другие террором?","tags":["История"],"draft":"Террором чаще кончаются те, что сносят все учреждения разом и ведут войну. Свободой — те, где старые институты переживают смену власти."},{"id":"o056","q":"Что современники не замечают в своём времени? Что не замечаем мы?","tags":["История"],"draft":"Обычно то, что всем кажется нормальным. Кандидаты у нас: обращение с животными, климат, отношение к старости."},{"id":"o057","q":"Чем память отличается от истории?","tags":["История"],"draft":"Память — то, что группа хочет помнить о себе. История — то, что можно проверить, включая неприятное."},{"id":"o058","q":"Какой период нашего времени историки будущего сочтут переломным?","tags":["История"]},{"id":"o059","q":"С кем из исторических фигур вы бы поужинали и о чём спросили бы?","tags":["История"]},{"id":"o060","q":"Какое когнитивное искажение вы чаще всего ловите у себя?","tags":["Психология"]},{"id":"o061","q":"Где в вашей жизни интуиция надёжнее расчёта и наоборот?","tags":["Психология"],"draft":"Интуиция надёжна там, где много раз получала быструю обратную связь. Где опыта нет или цена ошибки велика, лучше считать."},{"id":"o062","q":"Что вы делаете потому, что хотите, а что потому, что так принято?","tags":["Психология"]},{"id":"o063","q":"Можно ли по-настоящему понять другого человека?","tags":["Психология"],"draft":"До конца — нет, достаточно — да. Понимание проверяется тем, насколько точно предсказываешь, что человека обрадует или заденет."},{"id":"o064","q":"Как вы узнаёте, что ошиблись? Что этому мешает?","tags":["Психология"]},{"id":"o065","q":"Самообман: всегда ли он вреден?","tags":["Психология"],"draft":"Немного полезен: без лёгкой переоценки себя трудно начинать. Вреден, когда мешает видеть то, что ещё можно исправить."},{"id":"o066","q":"Почему умные люди верят в глупости?","tags":["Психология"],"draft":"Ум даёт умение защищать то, во что уже веришь. Убеждения держатся на принадлежности к своим, а не на доводах."},{"id":"o067","q":"Что вам труднее всего в себе принять?","tags":["Психология"]},{"id":"o068","q":"Терапия нужна всем или это мода?","tags":["Психология"],"draft":"Не всем, но многим полезна. Модой стала идея, что любую трудность надо лечить."},{"id":"o069","q":"Как отличить усталость от лени, а грусть от депрессии?","tags":["Психология"],"draft":"Усталость проходит после отдыха, лень — нет: обычно это нежелание делать именно это. У грусти есть причина и срок; депрессия отнимает интерес ко всему и длится неделями."},{"id":"o070","q":"Что на самом деле мотивирует вас: интерес, страх, признание?","tags":["Психология"]},{"id":"o071","q":"Вы бы подчинились в эксперименте Милгрэма? Почему вы так думаете?","tags":["Психология"],"draft":"Скорее всего да, как большинство. Те, кто отказывался, не были особенными, а уверенность в себе ничего не предсказывала."},{"id":"o072","q":"Насколько вы тот же человек с разными людьми?","tags":["Психология"]},{"id":"o073","q":"Чего вы хотите на самом деле, когда хотите успеха?","tags":["Психология"]},{"id":"o074","q":"Можно ли любить человека и не хотеть с ним жить?","tags":["Психология"],"draft":"Да. Любовь и совместимость в быту — разные вещи."},{"id":"o075","q":"Что из детства вы до сих пор несёте с собой?","tags":["Психология"]},{"id":"o076","q":"Зависть: что она сообщает о ваших желаниях?","tags":["Психология"],"draft":"Точнее любого теста показывает, чего хочется на самом деле: завидуем только тому, что считаем для себя возможным."},{"id":"o077","q":"Одиночество и уединение: где граница?","tags":["Психология"],"draft":"Уединение выбирают, и из него можно выйти. Одиночество — когда выйти не к кому."},{"id":"o078","q":"Как принимать важные решения при неполной информации?","tags":["Психология"],"draft":"Оценить цену ошибки и обратимость. Обратимое решать быстро, необратимое медленно, и заранее записать, что заставит передумать."},{"id":"o079","q":"Что бы вы посоветовали себе пять лет назад и послушались бы?","tags":["Психология"]},{"id":"o080","q":"Южная и Северная Корея имели одну географию и культуру. Что это доказывает и чего не доказывает?","tags":["Экономика"],"draft":"Доказывает, что институты могут перевесить географию и культуру. Не доказывает, что они всегда главное: это один случай, с внешними покровителями по обе стороны."},{"id":"o081","q":"Маркс был хорошим экономистом и плохим пророком или наоборот?","tags":["Экономика"],"draft":"Сильный диагност и слабый пророк: концентрацию капитала и кризисы описал точно, обнищание рабочих и крах капитализма — нет."},{"id":"o082","q":"2008 год: банки надо было спасать? Защитите обе позиции.","tags":["Экономика"],"draft":"Систему спасать надо было: остановка платежей ударила бы по всем. Ошибка в том, как: убытки легли на общество, а акционеры и менеджеры отделались легко."},{"id":"o083","q":"Объясните довод Хайека о знании на примере биржевого стакана.","tags":["Экономика"],"draft":"Каждая заявка несёт частное знание участника. Стакан сводит его в цену, которую никто в одиночку вычислить не мог бы."},{"id":"o084","q":"Почему бедные люди принимают решения, которые снаружи кажутся неразумными?","tags":["Экономика"],"draft":"Изнутри они разумны: когда денег нет, горизонт сжимается, ошибка стоит дороже, а внимание съедено сегодняшним днём."},{"id":"o085","q":"Миллиардеры — признак здоровой экономики или больной?","tags":["Экономика"],"draft":"Зависит от происхождения денег: от нового продукта — признак здоровья, от монополии и близости к власти — болезни."},{"id":"o086","q":"Вам дают базовый доход на всю жизнь. Что изменится в ваших решениях?","tags":["Экономика"]},{"id":"o087","q":"Какой один показатель, кроме ВВП, вы бы сделали главным для страны?","tags":["Экономика"],"draft":"Ожидаемая продолжительность здоровой жизни: в неё складываются доход, медицина, среда и безопасность."},{"id":"o088","q":"Финансы создают ценность или перераспределяют её? Ответьте на примере своей работы.","tags":["Экономика"]},{"id":"o089","q":"Высокочастотная торговля полезна обществу?","tags":["Экономика"],"draft":"Спреды сузились, и обычный инвестор платит меньше. Но часть прибыли — гонка скоростей, от которой обществу пользы нет."},{"id":"o090","q":"Справедлива ли цена, если на неё согласились обе стороны?","tags":["Экономика"],"draft":"Только если согласие было свободным: при нужде, обмане или монополии оно ничего не доказывает."},{"id":"o091","q":"Что нельзя продавать и покупать? Почему именно это?","tags":["Экономика"],"draft":"Людей, голоса на выборах, приговоры. То, что при продаже перестаёт быть собой или продаётся только от отчаяния."},{"id":"o092","q":"Наследство: право семьи или несправедливое преимущество?","tags":["Экономика"],"draft":"И то и другое. Желание передать детям естественно; крупные состояния через поколение становятся привилегией по рождению. Спор о ставке, а не о принципе."},{"id":"o093","q":"Экономический рост может продолжаться бесконечно?","tags":["Экономика"],"draft":"Материальный — нет. Рост ценности возможен за счёт знаний и услуг при падающем расходе ресурсов, но пока это удаётся лишь отчасти."},{"id":"o094","q":"Почему учителям платят меньше, чем трейдерам, и должно ли быть иначе?","tags":["Экономика"],"draft":"Зарплата отражает редкость навыка и то, сколько денег проходит через руки, а не пользу. Польза учителя распределена и в его доход не возвращается."},{"id":"o095","q":"Свободная торговля выгодна всем? Кто проигрывает?","tags":["Экономика"],"draft":"В сумме да, каждому — нет: проигрывают работники отраслей, которые конкурируют с импортом, и компенсируют им редко."},{"id":"o096","q":"Чему экономисты научились у кризисов, а чему нет?","tags":["Экономика"],"draft":"Научились тушить: давать ликвидность и не позволять банкам падать. Предотвращать не научились: каждый новый приходит оттуда, где не ждали."},{"id":"o097","q":"Деньги — это что? Попробуйте объяснить ребёнку.","tags":["Экономика"],"draft":"Общая запись о том, кто кому сколько должен, которой все верят."},{"id":"o098","q":"Жадность — двигатель или порок?","tags":["Экономика"],"draft":"Двигатель, пока правила направляют её на создание, а не на изъятие. Порок остаётся пороком, просто иногда полезным."},{"id":"o099","q":"Какая экономическая идея кажется вам очевидной, хотя большинство с ней не согласно?","tags":["Экономика"]},{"id":"o100","q":"Во что вы верите без доказательств и почему считаете это разумным?","tags":["Наука"],"draft":"Что мир существует вне моего сознания и что завтра законы природы будут те же. Доказать нельзя, но без этого нельзя и рассуждать."},{"id":"o101","q":"Чем научное утверждение отличается от ненаучного? Приведите пограничный пример.","tags":["Наука"],"draft":"Научное рискует: говорит, что должно наблюдаться и что его опровергнет. Пограничный пример — теория струн: математика строгая, проверки пока нет."},{"id":"o102","q":"Почему квантовую механику никто не понимает, а она работает?","tags":["Наука"],"draft":"Формулы дают предсказания с огромной точностью, но не говорят, что происходит между измерениями. Спорят о толковании, а не о расчётах."},{"id":"o103","q":"Что было до Большого взрыва: это вопрос или ошибка в вопросе?","tags":["Наука"],"draft":"Возможно, ошибка в вопросе: если время началось вместе со Вселенной, «до» не имеет смысла. Но это зависит от теории, которой пока нет."},{"id":"o104","q":"Какое научное открытие сильнее всего изменило то, кем мы себя считаем?","tags":["Наука"],"draft":"Эволюция: человек оказался не отдельным творением, а веткой общего дерева."},{"id":"o105","q":"Должна ли наука заниматься тем, что может быть использовано во зло?","tags":["Наука"],"draft":"Запрещать знание бесполезно, оно появится в другом месте. Контролировать стоит применение и самые опасные эксперименты."},{"id":"o106","q":"Можно ли доверять экспертам? Как выбирать, каким?","tags":["Наука"],"draft":"В их области и когда независимые специалисты согласны — да. За пределами области эксперт — обычный человек с мнением."},{"id":"o107","q":"Корреляция и причинность: где вы недавно их перепутали?","tags":["Наука"]},{"id":"o108","q":"Эволюция объясняет поведение человека или только оправдывает его?","tags":["Наука"],"draft":"Объясняет склонности, но не оправдывает поступки: «естественно» не значит «хорошо»."},{"id":"o109","q":"Что такое жизнь? Вирус живой?","tags":["Наука"],"draft":"Чёткой границы нет. Вирус размножается и эволюционирует, но своего обмена веществ у него нет: он на краю определения."},{"id":"o110","q":"Вы бы узнали свои генетические риски, если с ними ничего нельзя сделать?","tags":["Наука"]},{"id":"o111","q":"Кризис воспроизводимости подрывает доверие к науке или доказывает, что она работает?","tags":["Наука"],"draft":"И то и другое: он показал, что многое опубликованное неверно, и обнаружила это сама наука."},{"id":"o112","q":"Что наука не сможет объяснить никогда?","tags":["Наука"],"draft":"Возможно, почему вообще есть что-то, а не ничто. И, может быть, субъективный опыт."},{"id":"o113","q":"Красота теории — признак её истинности?","tags":["Наука"],"draft":"Хорошая подсказка, но не доказательство: история знает красивые ложные теории."},{"id":"o114","q":"Сколько денег разумно тратить на космос, пока есть бедность?","tags":["Наука"],"draft":"Доля космоса в бюджетах мала, а отдача в технологиях и знаниях велика. Противопоставление ложное: бедность не от того, что летают в космос."},{"id":"o115","q":"Старение — болезнь, которую надо лечить?","tags":["Наука"],"draft":"Механизмы старения стоит лечить, как любую причину болезней. Цель — здоровые годы, а не бессмертие."},{"id":"o116","q":"Почему люди отрицают науку и что с этим делать?","tags":["Наука"],"draft":"Не от незнания, а от недоверия и принадлежности к группе. Факты помогают плохо; помогают люди из своего круга, которым верят."},{"id":"o117","q":"Что бы вы хотели понять, если бы могли задать природе один вопрос?","tags":["Наука"]},{"id":"o118","q":"Чем объяснение отличается от предсказания?","tags":["Наука"],"draft":"Предсказать можно и без понимания, как барометр предсказывает бурю. Объяснение говорит почему и работает в новых условиях."},{"id":"o119","q":"Какая область науки через пятьдесят лет покажется нам такой же наивной, как алхимия?","tags":["Наука"],"draft":"Возможно, наука о питании и часть психологии: много корреляций, мало механизмов."},{"id":"o120","q":"Перед какой картиной вы стояли дольше всего и почему?","tags":["Искусство"]},{"id":"o121","q":"«Так и мой ребёнок нарисует»: что ответить?","tags":["Искусство"],"draft":"Возможно, нарисует, но не придумает это сделать в 1915 году. В таком искусстве важен шаг, а не ремесло."},{"id":"o122","q":"Нужно ли знать контекст, чтобы понимать картину?","tags":["Искусство"],"draft":"Чтобы испытать — нет, чтобы понять — да. Лучший порядок: сначала смотреть, потом читать."},{"id":"o123","q":"Копия, неотличимая от оригинала, стоит того же? Почему нет?","tags":["Искусство"],"draft":"Глазу — то же, нам — нет: мы ценим ещё связь с рукой автора и моментом создания. Так же ценят письмо от близкого человека."},{"id":"o124","q":"Красота объективна?","tags":["Искусство"],"draft":"Не полностью: есть общие для людей предпочтения вроде симметрии, остальное — культура и опыт."},{"id":"o125","q":"Должно ли искусство быть понятным?","tags":["Искусство"],"draft":"Не обязано, но должно вознаграждать усилие. Непонятность сама по себе не достоинство."},{"id":"o126","q":"Почему «Мона Лиза» самая знаменитая картина: из-за качества или из-за истории?","tags":["Искусство"],"draft":"Из-за истории: картина хороша, но всемирной её сделали кража 1911 года и тиражирование."},{"id":"o127","q":"Может ли искусство быть безнравственным и великим?","tags":["Искусство"],"draft":"Может. Сила формы и правота взгляда — разные оси; «Триумф воли» тому пример."},{"id":"o128","q":"Что современное искусство умеет такого, чего не умело старое?","tags":["Искусство"],"draft":"Работать с идеей, пространством и зрителем напрямую, а не только с изображением."},{"id":"o129","q":"Зачем ходить в музей, если всё есть в высоком разрешении?","tags":["Искусство"],"draft":"Ради масштаба, фактуры и того, что там нельзя пролистать."},{"id":"o130","q":"Дизайн и реклама — искусство?","tags":["Искусство"],"draft":"Могут быть, когда решение выходит за рамки задачи. Но цель у них другая, и судят их сначала по ней."},{"id":"o131","q":"Какое здание в Москве вы считаете красивым и можете ли объяснить почему?","tags":["Искусство"]},{"id":"o132","q":"Сносить или сохранять: кто решает, что ценно?","tags":["Искусство"],"draft":"Решать должны не только владелец и не только эксперты. Разумное правило: то, что нельзя восстановить, сносить в последнюю очередь."},{"id":"o133","q":"Что важнее в городе: красота или удобство?","tags":["Искусство"],"draft":"Удобство, но красота — его часть: в красивом месте хочется оставаться."},{"id":"o134","q":"Может ли государство решать, какое искусство поддерживать?","tags":["Искусство"],"draft":"Поддерживать — да, выбирать — через независимых экспертов. Когда чиновник решает о содержании, получается заказ."},{"id":"o135","q":"Чем вкус отличается от насмотренности?","tags":["Искусство"],"draft":"Насмотренность — запас увиденного. Вкус — умение выбирать и объяснять выбор. Первое нужно для второго."},{"id":"o136","q":"Почему столько великого искусства создано на заказ церкви и власти?","tags":["Искусство"],"draft":"У них были деньги, стены и потребность впечатлять. Заданная тема не мешала: художник решал свои задачи внутри заказа."},{"id":"o137","q":"Что бы вы повесили у себя дома и что это говорит о вас?","tags":["Искусство"]},{"id":"o138","q":"Искусство должно утешать или тревожить?","tags":["Искусство"],"draft":"И то и другое. Плохо, когда оно только утешает или только тревожит."},{"id":"o139","q":"Какое произведение вам не нравится, хотя вы понимаете, что оно великое?","tags":["Искусство"]},{"id":"o140","q":"Назовите фильм, где вы чувствуете руку режиссёра. По каким признакам?","tags":["Кино"]},{"id":"o141","q":"«Потёмкин» снят как пропаганда. Мешает ли это считать его великим?","tags":["Кино"],"draft":"Не мешает: монтажные открытия работают независимо от цели. Но помнить о ней нужно, чтобы видеть, как тобой управляют."},{"id":"o142","q":"Объясните разницу саспенса и сюрприза на сцене из недавнего фильма.","tags":["Кино"]},{"id":"o143","q":"Почему приёмы новой волны, когда-то скандальные, сегодня незаметны?","tags":["Кино"],"draft":"Потому что они победили: рваный монтаж, съёмка с рук и естественный свет стали обычным языком."},{"id":"o144","q":"Какое различие между «кино» и «контентом» вы готовы защищать?","tags":["Кино"],"draft":"Кино хочет, чтобы на него смотрели. Контент — чтобы его не выключали."},{"id":"o145","q":"Что вы теряете, когда смотрите фильм на ноутбуке? А что получаете?","tags":["Кино"],"draft":"Теряются масштаб, звук и невозможность поставить на паузу. Получаешь фильмы, которых нет в прокате."},{"id":"o146","q":"Какой один фильм вы бы показали, чтобы объяснить, зачем нужно кино?","tags":["Кино"]},{"id":"o147","q":"Медленное кино: глубина или претензия?","tags":["Кино"],"draft":"Бывает и то и другое. Проверка: меняется ли что-то в кадре или в тебе, пока он длится."},{"id":"o148","q":"Почему книга почти всегда «лучше фильма»? Есть ли обратные примеры?","tags":["Кино"],"draft":"Книга даёт мысли героя и длится дольше. Обратные примеры есть: «Крёстный отец», «Сталкер»."},{"id":"o149","q":"Сериал может быть сильнее фильма? В чём именно?","tags":["Кино"],"draft":"В развитии характеров: у него есть время. Уступает в цельности формы."},{"id":"o150","q":"Можно ли показывать насилие так, чтобы оно не становилось зрелищем?","tags":["Кино"],"draft":"Можно: не давать от него удовольствия и показывать последствия. «Иди и смотри» — пример."},{"id":"o151","q":"Что старые фильмы умеют такого, что разучились новые?","tags":["Кино"],"draft":"Доверять длинному плану и зрителю, которому не надо всё объяснять."},{"id":"o152","q":"Дубляж или субтитры? Что теряется в каждом случае?","tags":["Кино"],"draft":"Субтитры: голос — половина актёрской игры. Платишь частью внимания к кадру."},{"id":"o153","q":"Какой фильм вы пересматриваете и что это говорит о вас?","tags":["Кино"]},{"id":"o154","q":"Документальное кино правдивее игрового?","tags":["Кино"],"draft":"Не обязательно: в нём тоже выбирают, что снимать и как монтировать. Оно ближе к фактам, но не обязательно к правде."},{"id":"o155","q":"Спойлеры портят фильм?","tags":["Кино"],"draft":"Портят первый просмотр фильмов, построенных на повороте. Хороший фильм знание финала выдерживает."},{"id":"o156","q":"Какой фильм вы не поняли и почему это вас не отпускает?","tags":["Кино"]},{"id":"o157","q":"Тарковский: что он делает со временем и зачем?","tags":["Кино"],"draft":"Даёт плану длиться дольше, чем нужно для информации, и зритель начинает чувствовать само течение времени."},{"id":"o158","q":"Нужен ли фильму сюжет?","tags":["Кино"],"draft":"Нет, но нужно то, что держит внимание: ритм, вопрос, изменение."},{"id":"o159","q":"Какая сцена из кино осталась с вами на годы?","tags":["Кино"]},{"id":"o160","q":"Что из вашего плейлиста будут слушать через сто лет и почему?","tags":["Музыка"]},{"id":"o161","q":"Объясните на языке частот, почему квинта звучит согласно, а соседние клавиши режут слух.","tags":["Музыка"],"draft":"У квинты частоты относятся как 3:2, и многие обертоны совпадают. У соседних клавиш частоты близки и дают биения, которые слышны как шероховатость."},{"id":"o162","q":"Чем слушание симфонии отличается от слушания трёхминутной песни как занятие?","tags":["Музыка"],"draft":"Симфония требует держать в памяти темы и следить, как они меняются: это внимание на длинной дистанции. Песня даёт настроение сразу."},{"id":"o163","q":"Должно ли государство оплачивать оперные театры?","tags":["Музыка"],"draft":"Довод за: это наследие, которое рынок не сохранит. Довод против: платят все, ходят немногие. Компромисс — поддержка с условием доступности."},{"id":"o164","q":"Пятая симфония Шостаковича: покорность или скрытый протест? Можно ли это узнать из музыки?","tags":["Музыка"],"draft":"Из самой музыки узнать нельзя: финал слышится и как торжество, и как торжество из-под палки. Двусмысленность и была способом выжить."},{"id":"o165","q":"Где проходит ваша граница между «слушаю, зная» и «не слушаю»?","tags":["Музыка"]},{"id":"o166","q":"Импровизация в джазе: сочинение или исполнение?","tags":["Музыка"],"draft":"Сочинение в реальном времени: ноты выбираются на месте, но из языка, выученного годами."},{"id":"o167","q":"Если бы вам сказали, что любимую вещь написал алгоритм, что изменилось бы?","tags":["Музыка"]},{"id":"o168","q":"Почему музыка вызывает эмоции, хотя ничего не изображает?","tags":["Музыка"],"draft":"Музыка играет с ожиданием: создаёт напряжение и разрешает его. Темп и громкость к тому же прямо действуют на тело."},{"id":"o169","q":"Музыка без слов может что-то значить?","tags":["Музыка"],"draft":"Может, но не то, что слова: она передаёт форму чувства, а не его предмет."},{"id":"o170","q":"Фоновая музыка — это слушание?","tags":["Музыка"],"draft":"Нет, это атмосфера. Слушание начинается, когда следишь за тем, что происходит."},{"id":"o171","q":"Почему минор кажется грустным: природа или привычка?","tags":["Музыка"],"draft":"В основном привычка: в других культурах связь иная. Но низкий тон и медленный темп звучат печально почти везде."},{"id":"o172","q":"Что вы слышали вживую такого, что запись не передаёт?","tags":["Музыка"]},{"id":"o173","q":"Можно ли научиться любить музыку, которая сначала не нравится? Стоит ли?","tags":["Музыка"],"draft":"Можно: повторное слушание делает непривычное понятным. Стоит, если эту музыку ценят люди, чьему слуху доверяешь."},{"id":"o174","q":"Кавер может быть лучше оригинала? Пример.","tags":["Музыка"],"draft":"Может: Hallelujah у Джеффа Бакли, All Along the Watchtower у Хендрикса."},{"id":"o175","q":"Какая музыка была с вами в важный момент жизни?","tags":["Музыка"]},{"id":"o176","q":"Тишина — часть музыки?","tags":["Музыка"],"draft":"Да: пауза — такой же материал, как звук."},{"id":"o177","q":"Популярное значит плохое? Откуда это убеждение?","tags":["Музыка"],"draft":"Нет. Убеждение идёт от желания отличаться; популярность о качестве не говорит ничего ни в одну сторону."},{"id":"o178","q":"Чем исполнитель отличается от автора и кто из них важнее?","tags":["Музыка"],"draft":"В классике автор задаёт текст, исполнитель — прочтение. В джазе и поп-музыке граница стёрта, и исполнитель часто важнее."},{"id":"o179","q":"Какой альбом вы бы взяли как единственный на год?","tags":["Музыка"]},{"id":"o180","q":"Какую свою политическую позицию вы унаследовали, а какую выбрали?","tags":["Политика"]},{"id":"o181","q":"За какую идею противоположного лагеря вы могли бы поручиться?","tags":["Политика"]},{"id":"o182","q":"Может ли хороший человек быть хорошим политиком?","tags":["Политика"],"draft":"Может, но ему придётся принимать решения, после которых руки не остаются чистыми. Хороший политик это понимает и не привыкает."},{"id":"o183","q":"Патриотизм — добродетель?","tags":["Политика"],"draft":"Привязанность к своим — добродетель, пока не требует считать других хуже и молчать о собственных ошибках."},{"id":"o184","q":"Что государство вам должно и что вы должны ему?","tags":["Политика"],"draft":"Бесспорный минимум: государство даёт безопасность, суд и равные правила, гражданин соблюдает законы и платит налоги. Всё сверх этого — предмет спора."},{"id":"o185","q":"Большинство может быть неправо. Что тогда?","tags":["Политика"],"draft":"Для этого нужны права, которые не ставят на голосование, и суд, который их защищает."},{"id":"o186","q":"Голосовать — обязанность?","tags":["Политика"],"draft":"Доводы есть в обе стороны: один голос ничего не решает, но массовый отказ решает многое."},{"id":"o187","q":"Должны ли голоса знающих весить больше?","tags":["Политика"],"draft":"Соблазнительно, но кто определит знающих? Исторически цензы применяли, чтобы отсечь неудобных."},{"id":"o188","q":"Безопасность или частная жизнь: где вы проводите черту?","tags":["Политика"],"draft":"Слежка допустима адресно, по решению суда и с отчётом. Массовая и тайная — нет: злоупотребление вопрос времени."},{"id":"o189","q":"Справедливая война бывает?","tags":["Политика"],"draft":"Оборона от нападения — да. Критерии известны давно: правое дело, крайнее средство, соразмерность. Применять их честно трудно: каждая сторона считает своё дело правым."},{"id":"o190","q":"Можно ли вмешиваться в дела другой страны, чтобы остановить массовые убийства?","tags":["Политика"],"draft":"В принципе да, при массовых убийствах. На практике вмешательства часто делали хуже, и решает о них не нейтральный судья. Спор не закрыт."},{"id":"o191","q":"Национальное государство устарело?","tags":["Политика"],"draft":"Нет: это по-прежнему единственный уровень, где работают налоги, право и солидарность. Но климат и финансы оно в одиночку не решает."},{"id":"o192","q":"Санкции наказывают власть или людей?","tags":["Политика"],"draft":"Обычно и тех и других. Исследования показывают, что цели они достигают редко, а население платит заметно; адресные точнее."},{"id":"o193","q":"Почему люди голосуют против собственных экономических интересов?","tags":["Политика"],"draft":"Люди голосуют не только кошельком: идентичность, уважение и ценности для них не менее реальны."},{"id":"o194","q":"Компромисс — предательство принципов или суть политики?","tags":["Политика"],"draft":"Суть политики. Предательством он становится, когда сдают то, ради чего всё затевалось."},{"id":"o195","q":"Что опаснее: слишком сильное государство или слишком слабое?","tags":["Политика"],"draft":"Оба опасны по-разному: сильное без ограничений давит, слабое не защищает от тех, кто давит вместо него."},{"id":"o196","q":"Левые и правые: это деление ещё что-то объясняет?","tags":["Политика"],"draft":"Отчасти: в экономике ещё объясняет, в культуре и отношении к глобализации линии проходят иначе."},{"id":"o197","q":"Тюрьма должна наказывать или исправлять?","tags":["Политика"],"draft":"Изолировать опасных и возвращать остальных. По данным, жёсткость условий рецидив не снижает."},{"id":"o198","q":"Должны ли богатые страны платить бедным за изменение климата?","tags":["Политика"],"draft":"Довод за: они выбросили большую часть накопленного CO2. Довод против: нынешние поколения этого не выбирали. Практически без этих денег бедные страны на чистую энергию не перейдут."},{"id":"o199","q":"Какой закон вы бы приняли первым, если бы могли?","tags":["Политика"]},{"id":"o200","q":"Какая часть ваших достижений — заслуга, а какая — стартовые условия?","tags":["Общество"]},{"id":"o201","q":"Приведите пример личной проблемы, которая на деле общественная.","tags":["Общество"],"draft":"Выгорание: выглядит как личная слабость, а на деле следствие того, как устроена работа."},{"id":"o202","q":"Опишите свою «сцену» и «кулисы» по Гофману на работе.","tags":["Общество"]},{"id":"o203","q":"По каким мелочам вы определяете «своего» человека?","tags":["Общество"]},{"id":"o204","q":"Назовите обычай, который кажется вам неприемлемым. На каком основании вы его судите?","tags":["Общество"]},{"id":"o205","q":"Какой наш обычай покажется диким через сто лет?","tags":["Общество"],"draft":"Вероятно, промышленное животноводство и восемь часов в офисе пять дней в неделю."},{"id":"o206","q":"Вы бы запретили соцсети до 16 лет? Какие данные вас переубедили бы?","tags":["Общество"],"draft":"Запрет трудно исполнить, а данные о вреде неоднозначны. Убедили бы эксперименты, где ограничение заметно улучшает состояние подростков."},{"id":"o207","q":"Этот ваш проект с книгами: что в нём любопытство, а что накопление культурного капитала?","tags":["Общество"]},{"id":"o208","q":"Чем различаются мужчины и женщины и откуда вы это знаете?","tags":["Общество"],"draft":"В среднем есть различия в телосложении и некоторых склонностях, но разброс внутри каждой группы больше, чем между ними. Что здесь от биологии, а что от воспитания, наука разделяет плохо."},{"id":"o209","q":"Нужно ли заводить детей? Кому и что мы этим должны?","tags":["Общество"],"draft":"Никому. Это выбор, и у обоих вариантов есть достойные причины."},{"id":"o210","q":"Брак устарел?","tags":["Общество"],"draft":"Как обязанность — да, как выбор — нет: людям по-прежнему нужно публичное обещание."},{"id":"o211","q":"Большой город делает людей свободнее или более одинокими?","tags":["Общество"],"draft":"И то и другое, и это одна и та же анонимность: никто не следит и никто не заметит."},{"id":"o212","q":"Почему люди следуют моде?","tags":["Общество"],"draft":"Чтобы показать принадлежность к своим и отличие от чужих одновременно."},{"id":"o213","q":"Образование должно готовить к работе или к жизни?","tags":["Общество"],"draft":"К жизни, а работа — её часть. Навыки устаревают, умение учиться и думать — нет."},{"id":"o214","q":"Что вы считаете нормальным только потому, что выросли в Москве?","tags":["Общество"]},{"id":"o215","q":"Эмиграция: что человек теряет и что приобретает?","tags":["Общество"],"draft":"Теряет язык как родную среду, статус и круг. Приобретает дистанцию и второй взгляд на всё, включая дом."},{"id":"o216","q":"Должны ли богатые жертвовать больше и кто вправе этого требовать?","tags":["Общество"],"draft":"Морально — да: чем больше возможностей, тем больше ответственность. Требовать вправе только закон через налоги; остальное дело совести."},{"id":"o217","q":"Работа — источник смысла или способ платить за жизнь?","tags":["Общество"]},{"id":"o218","q":"Что такое успех и кто вам это сказал?","tags":["Общество"]},{"id":"o219","q":"Какой социальной нормы вам не хватает?","tags":["Общество"]},{"id":"o220","q":"Во что вы верите? Как бы вы назвали это, если не религией?","tags":["Религия"]},{"id":"o221","q":"Почему религии есть у всех известных обществ?","tags":["Религия"],"draft":"Она отвечает на общие нужды: объяснить смерть и случай, скрепить группу, придать вес правилам."},{"id":"o222","q":"Можно ли быть духовным без религии и что это значит?","tags":["Религия"],"draft":"Можно: это внимание к тому, что больше тебя, без догмата и общины. Но без общины и практики оно часто остаётся настроением."},{"id":"o223","q":"Если Бог есть, почему страдают невинные?","tags":["Религия"],"draft":"Удовлетворительного ответа нет. Свобода воли объясняет зло от людей, но не землетрясения и не болезни детей."},{"id":"o224","q":"Пари Паскаля: в чём его сила и где оно ломается?","tags":["Религия"],"draft":"Сила: при неопределённости учитывай размер ставки. Ломается на том, что богов много, а верить по расчёту нельзя."},{"id":"o225","q":"Вера — выбор?","tags":["Религия"],"draft":"Не прямо: решить поверить нельзя. Можно выбрать практику и окружение, в которых вера появляется или уходит."},{"id":"o226","q":"Что религия даёт такого, чего не даёт ничто другое?","tags":["Религия"],"draft":"Общину, ритуал на рождение и смерть, язык для благодарности и вины. По отдельности всё это есть и вне религии, вместе — редко."},{"id":"o227","q":"Чудо: как бы вы проверили сообщение о нём?","tags":["Религия"],"draft":"Спросить, что вероятнее: что закон природы нарушился или что свидетель ошибся. Это довод Юма."},{"id":"o228","q":"Нужны ли ритуалы неверующим?","tags":["Религия"],"draft":"Да: они отмечают переходы и собирают людей. Потому светские свадьбы и похороны повторяют религиозные."},{"id":"o229","q":"Почему священные тексты до сих пор читают?","tags":["Религия"],"draft":"В них сжат опыт вины, страдания и надежды, и на них стоит культура, в том числе у неверующих."},{"id":"o230","q":"Религия чаще разделяет людей или объединяет?","tags":["Религия"],"draft":"Объединяет внутри, разделяет снаружи: одно следует из другого."},{"id":"o231","q":"Смерть без веры в загробную жизнь: как с этим живут?","tags":["Религия"],"draft":"Конечность придаёт вес времени. Утешение в том, что останется в людях и делах."},{"id":"o232","q":"Все религии говорят об одном или о разном?","tags":["Религия"],"draft":"Нет. Этика похожа, но картины мира и цели разные: спасение, освобождение, гармония — не одно и то же."},{"id":"o233","q":"Можно ли уважать веру, считая её ложной?","tags":["Религия"],"draft":"Да: уважают человека и то, что вера для него делает, а не истинность её утверждений."},{"id":"o234","q":"Какую библейскую или мифологическую историю вы считаете самой глубокой?","tags":["Религия"]},{"id":"o235","q":"Книга Иова отвечает на вопрос о страдании или отказывается отвечать?","tags":["Религия"],"draft":"Отказывается, и в этом честна: Бог ничего не объясняет, но правым оказывается Иов, не принявший объяснений друзей."},{"id":"o236","q":"Буддийское «желание — причина страдания»: вы согласны?","tags":["Религия"],"draft":"Отчасти: цепляние за желаемое действительно мучит. Но жизнь без привязанностей — тоже потеря."},{"id":"o237","q":"Что в вашей жизни священно, то есть не подлежит торгу?","tags":["Религия"]},{"id":"o238","q":"Чем секта отличается от религии?","tags":["Религия"],"draft":"Секта изолирует от внешнего мира, наказывает за выход и замыкается на лидере. Возраст и размер не критерий."},{"id":"o239","q":"Что заменило религию тем, кто от неё ушёл?","tags":["Религия"],"draft":"Политика, психотерапия, забота о теле, фанатские сообщества. Каждая берёт одну функцию, ни одна — все."},{"id":"o240","q":"Какая технология изменила вашу жизнь сильнее всего и к лучшему ли?","tags":["Технологии"]},{"id":"o241","q":"Что вы перестали уметь из-за телефона?","tags":["Технологии"]},{"id":"o242","q":"Если ИИ пишет лучше вас, зачем учиться писать?","tags":["Технологии"],"draft":"Потому что писать — способ думать: пока не сформулировала, не знаешь, что думаешь."},{"id":"o243","q":"Что должно остаться человеческим, даже если машина делает это лучше?","tags":["Технологии"],"draft":"Решения о судьбе людей: приговор, диагноз, который сообщают в лицо, воспитание. Там важно, что отвечает человек."},{"id":"o244","q":"Могут ли у машины быть интересы, которые надо учитывать?","tags":["Технологии"],"draft":"Если у системы появятся переживания — да. Сейчас неизвестно, есть ли они и как это проверить."},{"id":"o245","q":"Кто отвечает, когда ошибается алгоритм?","tags":["Технологии"],"draft":"Тот, кто решил его применить и получает от этого выгоду. «Так решила система» не ответ."},{"id":"o246","q":"Ваши данные: это собственность, след или часть личности?","tags":["Технологии"],"draft":"Ближе к части личности: распоряжаться ими без вас нельзя, даже если формально вы их отдали."},{"id":"o247","q":"Технологии нейтральны?","tags":["Технологии"],"draft":"Нет: в устройство вещи вшито, что с ней легко делать. Бесконечная лента — не нейтральное решение."},{"id":"o248","q":"Что бы вы запретили изобретать, если бы могли?","tags":["Технологии"],"draft":"Запретить изобретение не получится. Ограничить можно самые опасные работы, как с патогенами."},{"id":"o249","q":"Прогресс можно остановить? А замедлить?","tags":["Технологии"],"draft":"Остановить — нет, пока есть конкуренция. Замедлить и направить — да: с клонированием человека получилось."},{"id":"o250","q":"Интернет сделал людей умнее или самоувереннее?","tags":["Технологии"],"draft":"И то и другое: знающим он дал больше знаний, уверенным — подтверждение."},{"id":"o251","q":"Вы бы поставили себе нейроимплант, улучшающий память?","tags":["Технологии"]},{"id":"o252","q":"Чему стоит учиться, если не знаешь, какие профессии останутся?","tags":["Технологии"],"draft":"Тому, что долго не устаревает: математика, письмо, языки, умение быстро входить в новое."},{"id":"o253","q":"Можно ли дружить с ИИ? Чем это отличалось бы от дружбы?","tags":["Технологии"],"draft":"Разговаривать — да. Дружба предполагает, что у другого есть своя жизнь и ты ему нужна; есть ли это здесь, неясно."},{"id":"o254","q":"Открытый код или закрытый: что безопаснее для мощных моделей?","tags":["Технологии"],"draft":"Открытость даёт проверку и не даёт власти сосредоточиться; закрытость не даёт опасному попасть ко всем. Специалисты расходятся, и ответ может зависеть от мощности модели."},{"id":"o255","q":"Какое решение вы никогда не доверите алгоритму?","tags":["Технологии"]},{"id":"o256","q":"Автоматизация вашей работы: что в ней нельзя заменить?","tags":["Технологии"]},{"id":"o257","q":"Нужно ли людям право не быть оценёнными машиной?","tags":["Технологии"],"draft":"Нужно право знать, что решение принял алгоритм, получить объяснение и потребовать пересмотра человеком."},{"id":"o258","q":"Кто должен владеть самыми мощными моделями: компании, государства, никто?","tags":["Технологии"],"draft":"У каждого варианта свой риск: компании не подотчётны, государства могут злоупотребить, «никто» неисполнимо. Полезнее спрашивать, кто их контролирует."},{"id":"o259","q":"Каким вы хотите видеть обычный день через тридцать лет?","tags":["Технологии"]},{"id":"n000","q":"Как понять, что исследованию о здоровье можно верить?","tags":["Медицина"],"draft":"Смотреть на тип: рандомизированное испытание на людях весит больше наблюдения, наблюдение больше опыта на мышах. Потом на размер выборки и на то, повторил ли результат кто-то ещё."},{"id":"n001","q":"Почему плацебо работает и что из этого следует?","tags":["Медицина"],"draft":"Часть эффекта — ожидание и внимание, часть — болезнь проходит сама. Следует не «вера лечит», а то, что любое лечение надо сравнивать с пустышкой."},{"id":"n002","q":"Чем корреляция в питании отличается от доказательства?","tags":["Медицина"],"draft":"Люди, которые едят «полезное», отличаются ещё сотней привычек. Пока нет эксперимента, это подсказка, а не причина."},{"id":"n003","q":"Какие проверки здоровья действительно нужны здоровому человеку?","tags":["Медицина"],"draft":"Немногие: давление, базовые анализы по возрасту, скрининги с доказанной пользой. Лишние обследования находят случайное и ведут к ненужному лечению."},{"id":"n004","q":"Нужны ли витамины и добавки?","tags":["Медицина"],"draft":"Большинству при обычном питании нет. Исключения конкретны: витамин D при дефиците, B12 веганам, фолиевая кислота при планировании беременности."},{"id":"n005","q":"Что на самом деле продлевает жизнь?","tags":["Медицина"],"draft":"Скучный набор: не курить, двигаться, спать, не набирать лишний вес, иметь близких людей. Всё остальное даёт проценты от этого."},{"id":"n006","q":"Почему антибиотики не помогают при простуде и чем опасно их пить «на всякий случай»?","tags":["Медицина"],"draft":"Простуду вызывают вирусы, а антибиотики действуют на бактерии. Лишний приём растит устойчивые штаммы и бьёт по своей микрофлоре."},{"id":"n007","q":"Как работает вакцина?","tags":["Медицина"],"draft":"Показывает иммунной системе безопасный фрагмент возбудителя, чтобы та заранее выработала память и при встрече ответила быстро."},{"id":"n008","q":"Здоровье — личная ответственность или общественное дело?","tags":["Медицина"],"draft":"И то и другое: привычки выбирает человек, но воздух, еду, доступ к врачу и деньги на здоровье определяет общество."},{"id":"n009","q":"Должна ли медицина быть бесплатной для всех?","tags":["Медицина"],"draft":"Довод за: болезнь не выбирают, а лечение одному не оплатить. Довод против: бесплатное нормируется очередями. Все богатые страны нашли свой компромисс, чистых моделей нет."},{"id":"n010","q":"Можно ли доверять врачу, если с ним не согласен интернет?","tags":["Медицина"],"draft":"Врачу, который объясняет и ссылается на рекомендации, — да. Второе мнение другого врача полезнее, чем форум."},{"id":"n011","q":"Где граница между нормой и болезнью в психике?","tags":["Медицина"],"draft":"Там, где состояние мешает жить и не проходит. Граница условна и сдвигается: то, что считали характером, стали лечить, и наоборот."},{"id":"n012","q":"Что вы делаете для своего здоровья из страха, а что из знания?","tags":["Медицина"]},{"id":"n013","q":"Старость — это болезнь?","tags":["Медицина"],"draft":"Спорят о слове. Бесспорно, что старение — главный фактор риска почти всех болезней и что его механизмы стоит изучать."},{"id":"n014","q":"Чему вас научила последняя болезнь?","tags":["Медицина"]},{"id":"n015","q":"Насколько география определяет судьбу страны?","tags":["География"],"draft":"Задаёт условия, но не приговор: выход к морю, климат и соседи важны, но одинаковая география давала разные исходы."},{"id":"n016","q":"Почему границы проходят там, где проходят?","tags":["География"],"draft":"Иногда по рекам и хребтам, чаще по итогам войн и договорам империй. Прямые линии на карте Африки и Ближнего Востока начерчены в европейских кабинетах."},{"id":"n017","q":"Почему почти все большие города стоят у воды?","tags":["География"],"draft":"Вода — это торговля, еда и транспорт. Город возникал там, где груз перекладывали с одного пути на другой."},{"id":"n018","q":"Что искажает привычная карта мира?","tags":["География"],"draft":"Проекция Меркатора раздувает север: Гренландия кажется размером с Африку, хотя меньше в четырнадцать раз. И Европа в центре — выбор картографа."},{"id":"n019","q":"Сколько людей может прокормить планета?","tags":["География"],"draft":"Нынешние восемь миллиардов кормит, и еды производится с запасом. Ограничение не в количестве, а в распределении и в цене для природы."},{"id":"n020","q":"Что будет со странами, где население сокращается?","tags":["География"],"draft":"Меньше работников на каждого пенсионера, пустеющие малые города. Выходы — миграция, более долгая работа, автоматизация; простого нет ни у кого."},{"id":"n021","q":"Какое место на карте вы не можете показать, хотя слышите о нём постоянно?","tags":["География"]},{"id":"n022","q":"Путешествия расширяют кругозор или только подтверждают ожидания?","tags":["География"],"draft":"Короткие — чаще подтверждают. Расширяет то, где приходится жить по чужим правилам хотя бы пару недель."},{"id":"n023","q":"Чем Север отличается от Юга, кроме температуры?","tags":["География"],"draft":"Сезонностью: там, где зима убивает, приходилось планировать и запасать. Насколько это объясняет различия культур, спорят."},{"id":"n024","q":"Почему Сибирь богата ресурсами и бедна людьми?","tags":["География"],"draft":"Холод, расстояния и реки, текущие на север, делают жизнь и вывоз дорогими. Ресурс можно добыть вахтой, город вахтой не построишь."},{"id":"n025","q":"Нужны ли вообще границы?","tags":["География"],"draft":"Они защищают то, что общество построило внутри, и они же закрепляют лотерею рождения. Обе вещи верны."},{"id":"n026","q":"Какую страну вы понимаете хуже всего и с чего начали бы?","tags":["География"]},{"id":"n027","q":"Что бы вы показали иностранцу, чтобы объяснить Россию?","tags":["География"]},{"id":"n028","q":"Какой ландшафт для вас «дом»?","tags":["География"]},{"id":"n029","q":"Изменение климата сильнее всего ударит по кому?","tags":["География"],"draft":"По бедным жарким странам и по жителям побережий и дельт: они меньше всего выбрасывали и меньше всего могут приспособиться."},{"id":"n030","q":"Зачем нужны законы, если есть совесть?","tags":["Право"],"draft":"Совесть у всех разная и не действует на тех, кому она не указ. Закон делает поведение других предсказуемым."},{"id":"n031","q":"Чем право отличается от справедливости?","tags":["Право"],"draft":"Право — это правила и процедура; справедливость — то, ради чего их писали. Они расходятся, и тогда спорят, менять закон или толкование."},{"id":"n032","q":"Почему лучше отпустить десять виновных, чем осудить одного невиновного?","tags":["Право"],"draft":"Ошибку в сторону обвинения нельзя вернуть, и она подрывает доверие к суду. Цена принципа — часть преступников на свободе, и общество её платит сознательно."},{"id":"n033","q":"Зачем виновному адвокат?","tags":["Право"],"draft":"Чтобы виновным его признал суд, а не следователь, и чтобы наказание было по закону, а не по настроению. Защита проверяет обвинение на прочность."},{"id":"n034","q":"Присяжные лучше профессионального судьи?","tags":["Право"],"draft":"Они менее привычны к обвинению и чаще оправдывают, но хуже разбираются в сложных доказательствах. Это спор о том, чьих ошибок мы боимся больше."},{"id":"n035","q":"Должен ли закон запрещать то, что вредит только самому человеку?","tags":["Право"],"draft":"Милль отвечает нет. Но чистых случаев мало: почти всё задевает семью, медицину, чужой пример. Спор идёт о том, где провести черту."},{"id":"n036","q":"Незнание закона не освобождает от ответственности. Справедливо ли это?","tags":["Право"],"draft":"Иначе незнание стало бы лучшей защитой. Но справедливо это только при условии, что законы опубликованы, понятны и их не слишком много."},{"id":"n037","q":"Можно ли судить по закону, принятому после поступка?","tags":["Право"],"draft":"Нет, это один из старейших принципов. Нюрнберг был исключением, и до сих пор спорят, оправданным ли."},{"id":"n038","q":"Что важнее: буква закона или его дух?","tags":["Право"],"draft":"Буква защищает от произвола судьи, дух — от абсурда. Хороший суд держится буквы, пока она не ведёт к явной нелепости."},{"id":"n039","q":"Чем договор отличается от обещания?","tags":["Право"],"draft":"Договор можно принудить исполнить через суд. В этом и смысл: он позволяет доверять незнакомым."},{"id":"n040","q":"Корпорация может быть виновной?","tags":["Право"],"draft":"Юридически да: её штрафуют и лишают лицензий. Морально виноваты люди, и штраф без личной ответственности часто становится ценой ведения дел."},{"id":"n041","q":"Какой закон вы нарушали и считаете, что правильно?","tags":["Право"]},{"id":"n042","q":"Должны ли права человека быть одинаковыми везде?","tags":["Право"],"draft":"Довод за: достоинство не зависит от паспорта. Довод против: список прав составлен в одной культурной традиции. На практике ядро почти общее, спор о периферии."},{"id":"n043","q":"Суд должен наказывать поступок или человека?","tags":["Право"],"draft":"Поступок: иначе судят за биографию и взгляды. Но при назначении наказания личность учитывают всегда, и это разумно."},{"id":"n044","q":"Какое право вы считаете самым важным и чем готовы ради него пожертвовать?","tags":["Право"]},{"id":"n045","q":"Влияет ли язык на то, как мы думаем?","tags":["Язык"],"draft":"Слабо, но измеримо: носители языков с разными словами для цветов чуть быстрее их различают. Сильная версия, что язык задаёт пределы мысли, не подтвердилась."},{"id":"n046","q":"Почему языки меняются и можно ли это остановить?","tags":["Язык"],"draft":"Потому что на них говорят: каждое поколение упрощает одно и усложняет другое. Остановить нельзя, можно только зафиксировать письменную норму."},{"id":"n047","q":"Заимствования портят язык?","tags":["Язык"],"draft":"Нет: русский уже пережил волны тюркских, греческих, немецких и французских слов и стал богаче. Лишнее отмирает само."},{"id":"n048","q":"Есть ли «правильный» язык?","tags":["Язык"],"draft":"Есть норма, удобная для общего понимания, и есть живая речь. Норма — договорённость, а не закон природы, и она со временем уступает."},{"id":"n049","q":"Чем язык отличается от диалекта?","tags":["Язык"],"draft":"Лингвистически почти ничем, границу проводит политика: язык — это диалект с армией и флотом."},{"id":"n050","q":"Стоит ли спасать вымирающие языки?","tags":["Язык"],"draft":"Каждый язык хранит уникальный способ описывать мир и память народа. Но решать, говорить ли на нём с детьми, вправе только сами носители."},{"id":"n051","q":"Нужны ли феминитивы?","tags":["Язык"],"draft":"Довод за: язык делает женщин видимыми в профессии. Довод против: новые слова звучат искусственно и подчёркивают пол там, где он неважен. Язык решит сам, какие приживутся."},{"id":"n052","q":"Что вы поняли о русском, когда начали учить французский?","tags":["Язык"]},{"id":"n053","q":"Можно ли думать без слов?","tags":["Язык"],"draft":"Да: образами, движением, музыкой, и младенцы с животными это подтверждают. Но сложное рассуждение без языка удержать трудно."},{"id":"n054","q":"Почему взрослому труднее выучить язык, чем ребёнку?","tags":["Язык"],"draft":"Произношение и грамматика «на слух» действительно легче даются до подросткового возраста. Зато взрослый быстрее набирает словарь и понимает правила."},{"id":"n055","q":"Мат — это бедность языка или его сила?","tags":["Язык"],"draft":"Сила в том, что он под запретом: слово действует, пока его нельзя. Бедностью он становится, когда заменяет все остальные слова."},{"id":"n056","q":"Перевод возможен?","tags":["Язык"],"draft":"Смысла — да, всего сразу — нет: приходится выбирать, чем жертвовать, ритмом, игрой слов или точностью."},{"id":"n057","q":"Какое слово вы недавно узнали и что оно вам открыло?","tags":["Язык"]},{"id":"n058","q":"Канцелярит: почему люди пишут сложнее, чем говорят?","tags":["Язык"],"draft":"Чтобы звучать солидно и ни за что не отвечать: «было принято решение» прячет того, кто решил."},{"id":"n059","q":"Смогут ли машины-переводчики сделать изучение языков ненужным?","tags":["Язык"],"draft":"Для справок и вывесок — уже. Для отношений, юмора и литературы нет: язык ещё и способ быть своим среди людей."},{"id":"n060","q":"Если бы все знали, о чём вы думаете, вы бы жили иначе?","tags":["Философия"]},{"id":"n061","q":"Чем знание отличается от правильной догадки?","tags":["Философия"],"draft":"Обоснованием: знающий может объяснить почему и не ошибся бы при чуть других обстоятельствах."},{"id":"n062","q":"Можно ли быть виноватым в том, чего не мог предвидеть?","tags":["Философия"],"draft":"За сам исход — нет, за небрежность — да. Но мы всё равно чувствуем вину за последствия, и это не совсем иррационально."},{"id":"n063","q":"Что такое «я», если мысли приходят сами?","tags":["Философия"],"draft":"Скорее процесс, чем вещь: рассказ, который мозг ведёт о себе. Это не делает его иллюзией, как не иллюзорна река."},{"id":"n064","q":"Справедливо ли, что красивым и умным легче?","tags":["Философия"],"draft":"Нет, но исправить это нельзя, не сделав хуже. Можно не добавлять к природной лотерее ещё и общественную."},{"id":"n065","q":"Долг перед собой существует?","tags":["Философия"],"draft":"Да: не растрачивать то, что тебе дано, и не обращаться с собой хуже, чем с другими."},{"id":"n066","q":"Простить — значит что?","tags":["Философия"],"draft":"Отказаться от права на возмездие, не объявляя поступок нормальным. Это решение, а не чувство, и оно не требует примирения."},{"id":"n067","q":"Что хуже: причинить зло или не предотвратить?","tags":["Философия"],"draft":"Причинить хуже, но разница меньше, чем нам удобно думать."},{"id":"n068","q":"Почему нам интересно читать о страданиях?","tags":["Литература"],"draft":"Это безопасная репетиция: проживаем то, чего боимся, и выходим целыми."},{"id":"n069","q":"Чем стиль отличается от красивости?","tags":["Литература"],"draft":"Стиль — когда иначе это сказать нельзя. Красивость — когда украшение можно убрать без потери."},{"id":"n070","q":"Какую книгу вы хвалите, хотя не дочитали?","tags":["Литература"]},{"id":"n071","q":"Автобиография — это правда?","tags":["Литература"],"draft":"Это правда о том, каким автор хочет себя помнить. Факты проверять по другим источникам."},{"id":"n072","q":"Детектив и фантастика — литература второго сорта?","tags":["Литература"],"draft":"Нет. В любом жанре есть вершины и поток, просто у «серьёзной» прозы поток быстрее забывают."},{"id":"n073","q":"Что важнее в романе: история или язык?","tags":["Литература"],"draft":"Без истории не дочитают, без языка не перечитают."},{"id":"n074","q":"Нужно ли знать биографию автора?","tags":["Литература"],"draft":"Для первого чтения нет. Потом она объясняет, почему книга написана так, но не что она значит."},{"id":"n075","q":"Правда ли, что историю нельзя изучать объективно?","tags":["История"],"draft":"Полностью нельзя: вопросы всегда задаёт настоящее. Но факты проверяемы, и честный историк отличим от пропагандиста."},{"id":"n076","q":"Что было бы, если бы не изобрели письменность?","tags":["История"],"draft":"Не было бы государств больше города, законов, науки и самой истории: всё, что сложнее памяти одного человека, требует записи."},{"id":"n077","q":"Могла ли промышленная революция не случиться?","tags":["История"],"draft":"Могла: условия складывались и раньше, в Китае и Риме, и не сработали. Она выглядит неизбежной только задним числом."},{"id":"n078","q":"Чья история в школьном учебнике?","tags":["История"],"draft":"Государства и победителей. Истории женщин, крестьян и окраин там меньше, чем их было в жизни."},{"id":"n079","q":"Какая историческая параллель с сегодняшним днём вам кажется ложной?","tags":["История"]},{"id":"n080","q":"Стоит ли стране извиняться за прошлое?","tags":["История"],"draft":"Извинение ничего не возвращает, но признаёт факт и закрывает спор о том, было ли. Без него разговор о будущем труднее."},{"id":"n081","q":"Что вы принимаете за черту характера, хотя это привычка?","tags":["Психология"]},{"id":"n082","q":"Почему мы помним плохое лучше хорошего?","tags":["Психология"],"draft":"Пропустить опасность дороже, чем упустить удовольствие, и мозг настроен соответственно."},{"id":"n083","q":"Можно ли доверять собственным воспоминаниям?","tags":["Психология"],"draft":"В общих чертах да, в деталях нет: каждое вспоминание — пересборка, и уверенность не говорит о точности."},{"id":"n084","q":"Прокрастинация — это про лень?","tags":["Психология"],"draft":"Нет, про избегание неприятного чувства: скуки, страха не справиться. Поэтому помогает не сила воли, а уменьшение задачи."},{"id":"n085","q":"Сравнивать себя с другими вредно?","tags":["Психология"],"draft":"С теми, кто далеко впереди, в чужой области — да. С собой прошлогодней и с теми, кто на шаг впереди, полезно."},{"id":"n086","q":"Чего люди на самом деле хотят, когда жалуются?","tags":["Психология"],"draft":"Чаще всего чтобы их услышали, а не починили. Стоит спросить, что нужно: совет или сочувствие."},{"id":"n087","q":"Почему всё дорожает?","tags":["Экономика"],"draft":"Денег в обращении становится больше, чем товаров, или производство дорожает. Небольшая инфляция — цель центробанков, а не их провал."},{"id":"n088","q":"Аренда или ипотека?","tags":["Экономика"],"draft":"Зависит от соотношения цены и аренды, ставки и того, как долго вы останетесь в городе. «Аренда — деньги на ветер» неверно: проценты по ипотеке тоже."},{"id":"n089","q":"Сколько денег достаточно?","tags":["Экономика"],"draft":"Столько, чтобы не думать о базовом и иметь запас на год. Дальше каждый рубль даёт всё меньше, а желания растут вместе с доходом."},{"id":"n090","q":"Реклама создаёт желания или обслуживает их?","tags":["Экономика"],"draft":"И то и другое: потребность в статусе и принадлежности она не создаёт, но привязывает к конкретной вещи."},{"id":"n091","q":"Справедлива ли плата за наследственный талант?","tags":["Экономика"],"draft":"Рынок платит за редкость, а не за заслугу. Справедливость здесь восстанавливают налогами, а не ценами."},{"id":"n092","q":"Почему трудно разбогатеть работой по найму?","tags":["Экономика"],"draft":"Зарплата растёт линейно, а капитал — в процентах от себя. Богатеют обычно через долю в чём-то, что растёт."},{"id":"n093","q":"Что значит «статистически значимо»?","tags":["Наука"],"draft":"Что такой результат редко получился бы случайно при отсутствии эффекта. Это не значит, что эффект большой или важный."},{"id":"n094","q":"Почему небо голубое?","tags":["Наука"],"draft":"Молекулы воздуха рассеивают короткие синие волны сильнее длинных красных, и синий свет приходит со всех сторон."},{"id":"n095","q":"Как мы знаем возраст Вселенной?","tags":["Наука"],"draft":"По скорости разбегания галактик и по реликтовому излучению. Независимые методы дают около 13,8 миллиарда лет."},{"id":"n096","q":"Что такое энтропия простыми словами?","tags":["Наука"],"draft":"Мера числа способов, которыми можно переставить частицы, не изменив картину в целом. Беспорядочных состояний больше, поэтому всё к ним идёт."},{"id":"n097","q":"Почему нельзя двигаться быстрее света?","tags":["Наука"],"draft":"Чем быстрее тело, тем больше энергии нужно на каждое следующее ускорение; у скорости света она становится бесконечной."},{"id":"n098","q":"Гомеопатия, астрология: почему в них верят образованные люди?","tags":["Наука"],"draft":"Они дают внимание, смысл и чувство контроля, а проверить на своём опыте нельзя: мы запоминаем совпадения."},{"id":"n099","q":"Что вы видите первым, когда смотрите на картину?","tags":["Искусство"]},{"id":"n100","q":"Зачем художники рисуют некрасивое?","tags":["Искусство"],"draft":"Потому что цель — правда или сила впечатления, а красота лишь один из способов."},{"id":"n101","q":"Мода — это искусство?","tags":["Искусство"],"draft":"Высокая — да, когда работает с формой и идеей. Но она ещё и индустрия, которой нужно, чтобы прошлый сезон устарел."},{"id":"n102","q":"Чем фотография отличается от картины, если обе можно подделать?","tags":["Искусство"],"draft":"Фотография сохраняет след того, что было перед объективом. Этот след и терялся с ретушью, а теперь с генерацией."},{"id":"n103","q":"Почему мы плачем над вымышленными людьми?","tags":["Кино"],"draft":"Чувства не проверяют, реален ли повод. Вымысел даёт пережить их без последствий."},{"id":"n104","q":"Чем хороший финал отличается от неожиданного?","tags":["Кино"],"draft":"Хороший кажется единственно возможным, когда оглядываешься назад."},{"id":"n105","q":"Экранизация обязана быть верной книге?","tags":["Кино"],"draft":"Духу — желательно, букве — нет: это другое искусство с другими средствами."},{"id":"n106","q":"Какой фильм изменил ваше мнение о чём-то?","tags":["Кино"]},{"id":"n107","q":"Почему одну и ту же песню хочется слушать сто раз?","tags":["Музыка"],"draft":"Мозгу приятно, когда ожидание сбывается, а знакомая музыка сбывается каждую секунду."},{"id":"n108","q":"Нужно ли понимать текст песни?","tags":["Музыка"],"draft":"Нет: голос работает как инструмент. Но понятый текст может песню и углубить, и испортить."},{"id":"n109","q":"Что музыка вашего поколения говорит о нём?","tags":["Музыка"]},{"id":"n110","q":"Чем патриот отличается от националиста?","tags":["Политика"],"draft":"Патриот любит своё, националист считает, что оно лучше чужого и важнее людей."},{"id":"n111","q":"Власть портит или показывает?","tags":["Политика"],"draft":"И то и другое: она снимает ограничения, и становится видно, что человек делал бы и раньше, если бы мог."},{"id":"n112","q":"Можно ли быть вне политики?","tags":["Политика"],"draft":"Можно не участвовать, но её решения всё равно касаются вас. Неучастие тоже позиция, просто её последствия выбирают другие."},{"id":"n113","q":"Что бы вы сделали иначе, оказавшись у власти, и почему это не делают сейчас?","tags":["Политика"]},{"id":"n114","q":"Чем вежливость отличается от лицемерия?","tags":["Общество"],"draft":"Вежливость не выдаёт себя за чувство, она просто облегчает совместную жизнь. Лицемерие изображает то, чего нет, ради выгоды."},{"id":"n115","q":"Одиночество — эпидемия или свобода?","tags":["Общество"],"draft":"Жить одному стали чаще по выбору, и многим так лучше. Проблема там, где нет ни одного человека, которому можно позвонить ночью."},{"id":"n116","q":"Что ваши бабушка и дедушка считали бы роскошью, а вы нормой?","tags":["Общество"]},{"id":"n117","q":"Каким должно быть хорошее образование?","tags":["Общество"],"draft":"Таким, после которого человек умеет учиться сам, отличать довод от мнения и не боится сложного."},{"id":"n118","q":"Что бы вас убедило в существовании Бога?","tags":["Религия"]},{"id":"n119","q":"Молитва и медитация — одно и то же?","tags":["Религия"],"draft":"Техника похожа: тишина, повторение, внимание. Разница в адресате: молитва обращена к кому-то, медитация ни к кому."},{"id":"n120","q":"Может ли атеист быть религиозным?","tags":["Религия"],"draft":"В смысле практики и принадлежности — да: многие соблюдают традицию без веры в догмат."},{"id":"n121","q":"Что вы делаете в телефоне, чего не выбирали бы осознанно?","tags":["Технологии"]},{"id":"n122","q":"Удобство стоит приватности?","tags":["Технологии"],"draft":"По мелочи мы уже ответили «да». Вопрос в том, обратима ли сделка: удобство можно вернуть, данные — нет."},{"id":"n123","q":"Чему школьников стоит учить, если ИИ решает задачи?","tags":["Технологии"],"draft":"Ставить задачи, проверять ответы и понимать, когда ответ неверен. Для этого всё равно придётся уметь решать самому."},{"id":"n124","q":"Должен ли ИИ говорить людям неприятную правду?","tags":["Технологии"],"draft":"Да, но так, как сказал бы хороший врач: по делу, без жестокости и когда об этом спросили."},{"id":"n125","q":"Почему в гороскопе почти каждый узнаёт себя?","tags":["Эзотерика"],"draft":"Это эффект Барнума: описания составлены так, что подходят большинству, а мы запоминаем попадания и не замечаем промахи."},{"id":"n126","q":"Откуда взялись двенадцать знаков зодиака?","tags":["Эзотерика"],"draft":"Вавилоняне разделили путь Солнца по небу на двенадцать равных частей по 30 градусов. С тех пор из-за прецессии созвездия сдвинулись примерно на знак."},{"id":"n127","q":"Проверяли ли астрологию по-настоящему?","tags":["Эзотерика"],"draft":"Да. В самом известном опыте 1985 года астрологи подбирали описание личности к натальной карте не лучше случайного."},{"id":"n128","q":"Почему люди обращаются к астрологии и таро, даже не веря в них?","tags":["Эзотерика"],"draft":"Они дают язык, чтобы говорить о себе, повод подумать о решении и чувство порядка. Это работает как зеркало, а не как прогноз."},{"id":"n129","q":"Откуда взялось таро?","tags":["Эзотерика"],"draft":"Из карточной игры в Италии XV века. Гадать на нём начали во Франции в XVIII веке, тогда же придумали «египетское происхождение»."},{"id":"n130","q":"Чем алхимия была полезна?","tags":["Эзотерика"],"draft":"Алхимики создали лабораторную посуду и методы: перегонку, возгонку, очистку. Ньютон и Бойль занимались ею всерьёз, химия выросла из неё."},{"id":"n131","q":"Что общего у эзотерических учений?","tags":["Эзотерика"],"draft":"Идея соответствий между большим и малым миром, скрытое знание для посвящённых и обещание личного преображения."},{"id":"n132","q":"Чем магия отличается от религии и от науки?","tags":["Эзотерика"],"draft":"Религия просит, магия принуждает, наука проверяет. Магия и наука обе хотят управлять миром, но только вторая согласна быть опровергнутой."},{"id":"n133","q":"Вредно ли безобидное суеверие?","tags":["Эзотерика"],"draft":"Пока оно не заменяет врача и не решает за человека, почти нет. Вред начинается, когда по нему выбирают лечение, партнёра или работника."},{"id":"n134","q":"Синхронистичность по Юнгу: наблюдение или ошибка мышления?","tags":["Эзотерика"],"draft":"Совпадений так много, что значимые обязаны случаться. Смысл в них вносим мы, но это не мешает им быть поводом что-то в себе заметить."},{"id":"n135","q":"Какой символ вам близок и почему?","tags":["Эзотерика"]},{"id":"n136","q":"Можно ли пользоваться таро как инструментом размышления?","tags":["Эзотерика"],"draft":"Можно: случайная картинка сбивает привычный ход мысли, как любая карточка с вопросом. Предсказания при этом никакого нет."},{"id":"n137","q":"Что такое доказательство: формальный вывод или убеждение сообщества?","tags":["Математика"],"draft":"На практике второе: статью проверяют люди, и доказательством считается то, что убедило специалистов. Формальная проверка возможна, но ею пользуются редко."},{"id":"n138","q":"Красота доказательства — это что?","tags":["Математика"],"draft":"Неожиданность плюс неизбежность: короткий ход, после которого непонятно, как можно было не увидеть."},{"id":"n139","q":"Почему математика описывает физический мир?","tags":["Математика"],"draft":"Возможно, потому что мы развивали те её части, что подходили к наблюдениям. Но это не объясняет, почему структуры, придуманные без всякой физики, потом находят в природе."},{"id":"n140","q":"Вероятность — свойство мира или мера нашего незнания?","tags":["Математика"],"draft":"Для монеты это незнание: исход определён, мы его не знаем. Для квантовых событий, по-видимому, свойство мира. В финансах почти всегда первое."},{"id":"n141","q":"Байесовский и частотный подходы: о чём спор на самом деле?","tags":["Математика"],"draft":"О том, можно ли приписывать вероятность гипотезе, а не только повторяемому событию. Байесовец отвечает да и платит выбором априорного распределения."},{"id":"n142","q":"Что вы принимаете на веру, когда пользуетесь моделью?","tags":["Математика"]},{"id":"n143","q":"Бесконечность существует?","tags":["Математика"],"draft":"Как математический объект — да, с ней работают строго. Есть ли что-то бесконечное в природе, неизвестно."},{"id":"n144","q":"Зачем чистая математика, если нужна прикладная?","tags":["Математика"],"draft":"Теория чисел сто лет считалась бесполезной, а потом на ней построили криптографию. Заранее не угадать, что пригодится."},{"id":"n145","q":"Может ли компьютерное доказательство, которое человек не способен проверить, считаться знанием?","tags":["Математика"],"draft":"Теорема доказана, но понимания не прибавилось. Математики ценят второе не меньше первого."},{"id":"n146","q":"Теорема Гёделя о неполноте: что она значит и чего не значит?","tags":["Математика"],"draft":"В любой достаточно богатой непротиворечивой системе есть истинные утверждения, которые в ней не доказать. Она не значит, что «истина недостижима» или что разум выше машины."},{"id":"n147","q":"Какая математическая идея изменила то, как вы видите обычную жизнь?","tags":["Математика"]},{"id":"n148","q":"Почему люди боятся математики?","tags":["Математика"],"draft":"Её учат как набор процедур без смысла, и первая же непонятая тема обрушивает всё следующее. Это свойство преподавания, а не предмета."},{"id":"n149","q":"Что вы на самом деле ищете в партнёре, если убрать то, что принято называть?","tags":["Отношения"]},{"id":"n150","q":"Совместимость находят или строят?","tags":["Отношения"],"draft":"Скорее строят: исходное совпадение ценностей нужно, но привычки, быт и способ ссориться вырабатываются вместе."},{"id":"n151","q":"Почему нас тянет к тем, с кем трудно?","tags":["Отношения"],"draft":"Знакомое с детства принимается за близость: тревога и неопределённость ощущаются как сильное чувство."},{"id":"n152","q":"Ревность — доказательство любви?","tags":["Отношения"],"draft":"Нет, это страх потери. Она показывает, насколько человек встревожен, а не насколько любит."},{"id":"n153","q":"Нужно ли говорить партнёру всё?","tags":["Отношения"],"draft":"Всё, что влияет на его решения, — да. Каждую мысль и каждую старую историю — нет: честность не то же, что отсутствие границ."},{"id":"n154","q":"Можно ли остаться друзьями после расставания?","tags":["Отношения"],"draft":"Можно, если оба этого хотят по одной причине и прошло время. Часто «друзья» — способ не отпускать."},{"id":"n155","q":"Чем ссора полезна?","tags":["Отношения"],"draft":"Она показывает, что важно обоим. Вредит не ссора, а презрение, уход в молчание и счёт старых обид."},{"id":"n156","q":"Дружба требует работы?","tags":["Отношения"],"draft":"Да, просто другой: инициативы. Дружбы взрослых умирают не от конфликтов, а от того, что никто не пишет первым."},{"id":"n157","q":"Сколько близких людей вам нужно?","tags":["Отношения"]},{"id":"n158","q":"Что вы узнали о себе из последних отношений?","tags":["Отношения"]},{"id":"n159","q":"Моногамия — природа или договор?","tags":["Отношения"],"draft":"Договор, опирающийся на природные склонности к привязанности и ревности. Люди способны и на верность, и на измену, и культура выбирает, что поощрять."},{"id":"n160","q":"Приложения для знакомств помогают или мешают?","tags":["Отношения"],"draft":"Помогают встретить тех, кого иначе не встретил бы. Мешают тем, что превращают людей в каталог и поощряют искать дальше."},{"id":"n161","q":"Почему вкусное часто вредно?","tags":["Еда"],"draft":"Тяга к сладкому, жирному и солёному полезна там, где их мало. Промышленность научилась давать всё сразу без насыщения."},{"id":"n162","q":"Что на самом деле делает еду вкусной?","tags":["Еда"],"draft":"Баланс соли, жира, кислоты и температуры плюс контраст текстур. Большинство «невкусных» блюд недосолены или им не хватает кислоты."},{"id":"n163","q":"Есть ли объективно хорошая кухня?","tags":["Еда"],"draft":"Техника объективна: пережаренное пережарено. Что считать вершиной, определяют привычка и культура."},{"id":"n164","q":"Можно ли доверять науке о питании?","tags":["Еда"],"draft":"Общим выводам — да: больше овощей, меньше переработанного. Утверждениям о конкретном продукте — с осторожностью: такие исследования почти всегда наблюдательные."},{"id":"n165","q":"Почему французская кухня считается главной?","tags":["Еда"],"draft":"Франция первой записала технику, создала ресторан и систему обучения поваров. Это победа кодификации, а не только вкуса."},{"id":"n166","q":"Что вы едите по привычке, а не потому, что хотите?","tags":["Еда"]},{"id":"n167","q":"Готовить самой — необходимость или удовольствие?","tags":["Еда"],"draft":"Навык на десяти блюдах окупается всю жизнь деньгами и здоровьем. Удовольствием он становится, когда перестаёт быть усилием."},{"id":"n168","q":"Вегетарианство: этика, экология или здоровье?","tags":["Еда"],"draft":"Самый сильный довод экологический и этический. Для здоровья важнее не отказ от мяса, а количество растений в рационе."},{"id":"n169","q":"Дорогое вино правда лучше?","tags":["Еда"],"draft":"До некоторого порога да, дальше платят за редкость и имя. В слепых дегустациях непрофессионалы дорогое от среднего не отличают."},{"id":"n170","q":"Еда — это культура или топливо?","tags":["Еда"],"draft":"И то и другое, и плохо, когда остаётся только одно: совместная еда — один из немногих ритуалов, доживших до наших дней."},{"id":"n171","q":"Какое блюдо для вас дом?","tags":["Еда"]},{"id":"n172","q":"Почему диеты не работают в долгую?","tags":["Еда"],"draft":"Тело защищает привычный вес, а запреты повышают тягу. Работает то, что можно делать годами."},{"id":"n173","q":"Зачем заниматься спортом, если не ради внешности?","tags":["Спорт"],"draft":"Ради того, каким будет тело в шестьдесят и восемьдесят, ради сна и настроения. Эффект на вес как раз скромный."},{"id":"n174","q":"Что важнее: кардио или сила?","tags":["Спорт"],"draft":"Нужны оба. Если выбирать одно, чем мы старше, тем важнее сила: мышцы и кости теряются сами."},{"id":"n175","q":"Талант или труд?","tags":["Спорт"],"draft":"На вершине нужны оба, и гены задают потолок. Но до своего потолка почти никто не доходит, так что обычному человеку решает труд."},{"id":"n176","q":"Почему мы болеем за команду?","tags":["Спорт"],"draft":"Это безопасная принадлежность к племени: общие ритуалы, враг и чувства, которые не стыдно показывать."},{"id":"n177","q":"Спорт высших достижений полезен обществу?","tags":["Спорт"],"draft":"Он даёт зрелище и примеры, но самих спортсменов часто калечит. Массовому здоровью помогают дворы и бассейны, а не медали."},{"id":"n178","q":"Допинг: почему бы не разрешить?","tags":["Спорт"],"draft":"Тогда придётся принимать всем, включая подростков, и соревноваться начнут фармакологи. Запрет защищает тех, кто не хочет рисковать здоровьем."},{"id":"n179","q":"Что вы узнаёте о себе, когда тяжело физически?","tags":["Спорт"]},{"id":"n180","q":"Киберспорт и шахматы — спорт?","tags":["Спорт"],"draft":"Если спорт — это соревнование с правилами и подготовкой, да. Если обязательно тело, шахматы ближе, чем кажется: пульс и расход энергии там серьёзные."},{"id":"n181","q":"Соревноваться или заниматься для себя?","tags":["Спорт"],"draft":"Соревнование даёт цель и честную обратную связь, но легко съедает удовольствие. Многим достаточно соревноваться с собой прошлогодней."},{"id":"n182","q":"Почему привычка к движению так трудно закрепляется?","tags":["Спорт"],"draft":"Награда отложена, а усилие сейчас. Работает привязка к расписанию и к людям, а не мотивация."},{"id":"n183","q":"Какой вид движения вам по-настоящему нравится?","tags":["Спорт"]},{"id":"n184","q":"Статистика убила красоту спорта?","tags":["Спорт"],"draft":"Сделала игру эффективнее и местами однообразнее. Но и дала увидеть ценность игроков, которых глазом не замечали."},{"id":"n185","q":"Мода — искусство, индустрия или язык?","tags":["Мода"],"draft":"Всё сразу: кутюр работает как искусство, масс-маркет как индустрия, а одежда на человеке всегда что-то сообщает."},{"id":"n186","q":"Что ваша одежда говорит о вас и хотите ли вы это говорить?","tags":["Мода"]},{"id":"n187","q":"Почему мода меняется?","tags":["Мода"],"draft":"Чтобы отличаться: когда стиль перенимают все, тем, кто его ввёл, нужен новый. К этому добавилась индустрия, которой нужны продажи каждый сезон."},{"id":"n188","q":"Хороший вкус существует?","tags":["Мода"],"draft":"Существует умение: пропорции, посадка, уместность. А что именно считать красивым, определяет среда, и это меняется."},{"id":"n189","q":"Дорогая вещь лучше дешёвой?","tags":["Мода"],"draft":"До некоторой цены растёт качество ткани и пошива, дальше платят за имя. Отличать помогает не ценник, а швы, состав и посадка."},{"id":"n190","q":"Следить за модой — поверхностно?","tags":["Мода"],"draft":"Не больше, чем следить за архитектурой. Поверхностно позволять ей решать за тебя."},{"id":"n191","q":"Быстрая мода: кто виноват?","tags":["Мода"],"draft":"Система, в которой дешевизна оплачена трудом и природой далеко от покупателя. Личный выбор помогает мало, но носить вещь тридцать раз, а не три — уже разница."},{"id":"n192","q":"Почему мужской костюм почти не меняется, а женская одежда меняется постоянно?","tags":["Мода"],"draft":"Костюм двести лет назад стал знаком серьёзности и власти. Женской одежде досталась роль украшения, и только в XX веке это начало сходиться."},{"id":"n193","q":"Униформа освобождает или обезличивает?","tags":["Мода"],"draft":"Тех, кому одежда не важна, освобождает. Обезличивает, когда её навязывают тем, кому важна."},{"id":"n194","q":"Можно ли одеваться «вне моды»?","tags":["Мода"],"draft":"Нет: отказ тоже читается как высказывание. Можно только выбрать, насколько сознательно его делать."},{"id":"n195","q":"Что такое стиль в отличие от моды?","tags":["Мода"],"draft":"Мода — то, что предлагают сейчас. Стиль — то, что вы отбираете и повторяете, потому что это вы."},{"id":"n196","q":"Какую вещь вы носите много лет и почему именно её?","tags":["Мода"]},{"id":"n197","q":"Для чего вам деньги?","tags":["Деньги"]},{"id":"n198","q":"Сколько нужно откладывать?","tags":["Деньги"],"draft":"Общее правило: столько, чтобы запас на полгода расходов появился за год-два, а дальше заметную долю дохода. Точная цифра зависит от того, насколько стабилен доход."},{"id":"n199","q":"Почему профессионалу рынка не стоит выбирать акции для личных денег?","tags":["Деньги"],"draft":"Личный счёт не даёт преимуществ рабочего места, а даёт издержки и конфликт интересов. Большинству профессионалов хватает широкого фонда."},{"id":"n200","q":"Что рискованнее: вложить или держать на счёте?","tags":["Деньги"],"draft":"На коротком сроке рискованнее акции, на длинном — наличные: инфляция съедает их наверняка. Риск зависит от горизонта."},{"id":"n201","q":"Нужно ли покупать квартиру?","tags":["Деньги"],"draft":"Это решение о жизни, а не только о деньгах. Финансово аренда и покупка ближе друг к другу, чем кажется; покупка выигрывает, если жить на месте долго."},{"id":"n202","q":"Копить или жить сейчас?","tags":["Деньги"],"draft":"Обе крайности ошибочны: часть опыта доступна только в молодости, а без запаса любая неприятность становится катастрофой."},{"id":"n203","q":"Как размер ставки важнее выбора актива?","tags":["Деньги"],"draft":"Хорошая ставка слишком большого размера разоряет так же надёжно, как плохая. Критерий Келли даёт верхнюю границу, на практике берут долю от неё."},{"id":"n204","q":"Говорить ли о деньгах с друзьями и партнёром?","tags":["Деньги"],"draft":"С партнёром обязательно и рано: это главный источник ссор. С друзьями полезно: молчание выгодно только тем, кто платит зарплаты."},{"id":"n205","q":"Что вы покупаете, чтобы казаться, а не быть?","tags":["Деньги"]},{"id":"n206","q":"Долг — это всегда плохо?","tags":["Деньги"],"draft":"Долг под то, что приносит больше, чем стоит, разумен. Долг под потребление по высокой ставке почти всегда нет."},{"id":"n207","q":"Сколько стоит ваше время?","tags":["Деньги"]},{"id":"n208","q":"Деньги делают счастливее?","tags":["Деньги"],"draft":"Да, и дольше, чем считалось: связь видна и на высоких доходах. Но каждый следующий рубль даёт меньше, а способ тратить важнее суммы."}];
